window.__PHD.push(" \"https://www.lancaster.ac.uk/arts/people/paul-cureton\", \"now\": null, \"background\": null, \"chinese_or_csc\": null}], \"total_estimate\": \"\u5728\u8bfb\u22651\uff08\u516c\u5f00\u5217\u51fa\uff09/ 2025\u20132026 \u6bd5\u4e1a6\uff08Pure+LinkedIn\uff09\uff0c\u603b\u91cf\u4f30\u8ba1\u7ea68\u201310\", \"student_pattern_zh\": \"\u8bbe\u8ba1\u5b66\u9662\u5b9e\u8df5+\u793e\u4f1a\u7814\u7a76\u578b\uff1a\u57ce\u5e02\u8bbe\u8ba1\u3001\u5730\u7406\u8bbe\u8ba1/\u6570\u5b57\u5b6a\u751f\u3001\u5bfc\u89c6\u3001\u591c\u666f\u57ce\u5e02\u3001\u9002\u8001\u5316\u3001\u8bbe\u8ba1\u9886\u5bfc\u529b\u4e0eAI\u8bbe\u8ba1\u5b9e\u8df5\uff1b\u65b9\u6cd5\u591a\u4e3a\u6848\u4f8b\u7814\u7a76\u3001\u53c2\u4e0e\u5f0f\u5de5\u4f5c\u574a\u3001\u6846\u67b6/\u5de5\u5177\u5305\u4ea7\u51fa\uff0c\u8bba\u6587\u7bc7\u5e45\u957f\uff08300\u2013950\u9875\uff09\u3002\", \"design_background_ok_zh\": \"\u660e\u786e\u53ef\u4ee5\uff1a\u5168\u90e8\u4e3a\u8bbe\u8ba1\u5b66\u9662\uff08PhD Design\uff09\u5b66\u751f\uff0c\u8bfe\u9898\u504f\u8bbe\u8ba1\u5b9e\u8df5\u4e0e\u8bbe\u8ba1\u7ba1\u7406\uff0c\u63a5\u53d7\u8bbe\u8ba1\u80cc\u666f\u3002\", \"chinese_students_zh\": \"\u4e2d\u56fd\u5b66\u751f\u6bd4\u4f8b\u5f88\u9ad8\uff1aXuan Gao\uff08\u4e2d\u56fd\u8bbe\u8ba1\u9886\u5bfc\u529b\uff09\u3001Xiaotong Song\uff08\u90d1\u5dde\u56fd\u68c9\u4e09\u5382\uff09\u3001Lisha He\u3001J. Liu\u3001\u5728\u8bfb Chengyuan An\uff1b\u6765\u6e90\u672a\u5199CSC\u3002\", \"implication_zh\": \"\u5bf9\u8bbe\u8ba1\u80cc\u666f+\u4e2d\u56fd\u6848\u4f8b\u975e\u5e38\u53cb\u597d\uff0c\u53ef\u5f15\u7528 Xiaotong Song \u7684\u90d1\u5dde\u5de5\u4e1a\u9057\u4ea7\u793e\u533a\u6848\u4f8b\u6216 J. Liu \u5bfc\u89c6\u8bbe\u8ba1\uff0c\u628a\u6cc9\u5dde\u975e\u9057/\u535a\u7269\u9986\u7a7a\u95f4\u53d9\u4e8b\u4f5c\u4e3a\u6848\u4f8b\uff1bCureton\u504f\u57ce\u5e02/\u6570\u5b57\u5b6a\u751f/\u4e25\u8083\u6e38\u620f\uff0c\u82e5\u4e3b\u6253\u624b\u52bf\u4ea4\u4e92+\u53d9\u4e8b\u7167\u660e\u9700\u642d\u914d Gradinar \u6216 Coulton\u3002\u98ce\u9669\uff1a\u5b66\u751f\u591a\u3001\u4e2d\u56fd\u751f\u591a\uff0c\u7ade\u4e89\u4e0e\u540c\u8d28\u5316\uff1b\u5956\u5b66\u91d1\u591a\u4e3a\u81ea\u8d39\u6216CSC\u3002\", \"sources\": [\"https://research.lancaster-university.uk/en/persons/paul-cureton/supervised/\", \"https://www.linkedin.com/posts/paul-cureton-41869129_what-a-brutal-month-of-unrelenting-work-activity-7422294158544908288-3Cwv\", \"https://eprints.lancs.ac.uk/id/eprint/238297\", \"https://www.lancaster.ac.uk/arts/people/paul-cureton\"], \"searched\": [\"Lancaster Pure Supervised Work\", \"Lancaster \u4e2a\u4eba\u9875 PhD Students\", \"Cureton LinkedIn\uff08\u7b54\u8fa9\u516c\u544a\uff09\", \"Lancaster EPrints\", \"Future Environments Lab \u56e2\u961f\u9875\"]}, \"title_zh\": \"\u8bbe\u8ba1\u5b66\u9ad8\u7ea7\u8bb2\u5e08\uff08\u526f\u6559\u6388\uff09\uff1b\u672a\u6765\u73af\u5883\u5b9e\u9a8c\u5ba4\u8d1f\u8d23\u4eba\", \"unit_zh\": \"\u8bbe\u8ba1\u5b66\u9662 / ImaginationLancaster\", \"evidence_projects_funding_zh\": \"\u4e3b\u9875\uff1aDSI MAGE\u2014\u2014\u83ab\u514b\u59c6\u5730\u533a\u6e38\u620f\u73af\u5883\uff08Morecambe Area Gaming Environment\uff0c2025-27\uff09\uff1b\u672a\u6765\u65e0\u4eba\u673a\u5929\u7a7a\uff08Future drone skies\uff09\uff1b\u6211\u4eec\u7684\u672a\u6765\u6d77\u5cb8\uff08Our Future Coast\uff09\uff1b\u535a\u58eb\u6307\u5bfc\u5174\u8da3\uff1a\u8bbe\u8ba1\u6846\u67b6\u3001\u6570\u5b57\u89c4\u5212\u3001\u65b0\u5174\u6280\u672f\u3001\u7cfb\u7edf\u4e0e\u6e38\u620f\uff1b\u8457\u4f5c\u300a\u65e0\u4eba\u673a\u672a\u6765\u300b\uff08Drone Futures\uff0c2020\uff09\u3002\", \"email_hook_zh\": \"\u60a8\u5173\u4e8e\u57fa\u4e8e\u6e38\u620f\u7684\u4e16\u754c\u6784\u5efa\u4e0e\u53c2\u4e0e\u5f0f\u4e25\u8083\u6e38\u620f\u7684\u7814\u7a76\uff0c\u4e3a\u8ba9\u89c2\u4f17\u53c2\u4e0e\u5171\u540c\u8bbe\u8ba1\u6211\u9057\u4ea7\u539f\u578b\u4e2d\u7684\u624b\u52bf\u2014\u5149\u6620\u5c04\u63d0\u4f9b\u4e86\u601d\u8def\u3002\", \"csc_status_zh\": \"\u6d3b\u8dc3\"}, {\"name\": \"Sijia Xiao\", \"school_en\": \"University of Vienna \u2013 Faculty of Computer Science (UniVie Doctoral School Computer Science, Autumn Call 2026)\", \"school_zh\": \"\u7ef4\u4e5f\u7eb3\u5927\u5b66\", \"country\": \"\", \"title\": \"Assistant Professor of Human-Computer Interaction (starting November 2026)\", \"unit\": \"Cooperative Systems, Faculty of Computer Science, University of Vienna\", \"homepage\": \"https://www.applexiao.com/\", \"email\": null, \"relevance\": 3, \"claim\": \"\u8096\u601d\u4f73\u662f\u672c DoCS \u804c\u4f4d\uff08Job ID 6163, HCI/Responsible AI/Social Computing\uff09\u7684\u62db\u8058\u5bfc\u5e08\uff0c2026 \u5e74 11 \u6708\u8d77\u4efb\u7ef4\u4e5f\u7eb3\u5927\u5b66 HCI \u52a9\u7406\u6559\u6388\uff1b\u65b9\u5411\u662f\u8d1f\u8d23\u4efb AI \u4e0e\u793e\u4f1a\u8ba1\u7b97\uff0c\u4e0e\u7528\u6237\u65b9\u5411\u76f8\u5173\u5ea6\u4f4e\u3002\", \"evidence_homepage\": \"https://www.applexiao.com/\", \"evidence_papers\": [{\"title\": \"Vipera: Blending Visual and LLM-Driven Guidance for Systematic Auditing of Text-to-Image Generative AI\", \"year\": 2026, \"venue\": \"CHI 2026\", \"url\": \"https://doi.org/10.1145/3772318.3791942\", \"link_to_user\": \"\u89c6\u89c9\u5316\u5ba1\u8ba1\u751f\u6210\u5f0f\u56fe\u50cf AI \u2192 \u6587\u5316\u9057\u4ea7\u56fe\u50cf\u751f\u6210\u4e2d\u7684\u504f\u89c1/\u8bef\u8bfb\u95ee\u9898\", \"title_zh\": \"Vipera\uff1a\u878d\u5408\u53ef\u89c6\u5316\u4e0eLLM\u9a71\u52a8\u5f15\u5bfc\uff0c\u7cfb\u7edf\u5ba1\u8ba1\u6587\u751f\u56fe\u751f\u6210\u5f0f\u4eba\u5de5\u667a\u80fd\"}, {\"title\": \"Investigating How Leaders Decide on AI Innovations: Opportunities for HCI\", \"year\": 2026, \"venue\": \"CHI 2026\", \"url\": \"https://doi.org/10.1145/3772318.3790484\", \"link_to_user\": \"AI \u521b\u65b0\u51b3\u7b56 \u2192 \u535a\u7269\u9986\u5f15\u5165 AI/XR \u7684\u673a\u6784\u89c6\u89d2\", \"title_zh\": \"\u63a2\u7a76\u9886\u5bfc\u8005\u5982\u4f55\u51b3\u7b56 AI \u521b\u65b0\uff1a\u4eba\u673a\u4ea4\u4e92\u7684\u673a\u9047\"}, {\"title\": \"SnuggleSense: Empowering Online Harm Survivors Through a Structured Sensemaking Process\", \"year\": 2025, \"venue\": \"Proc. ACM HCI (CSCW 2025)\", \"url\": \"https://doi.org/10.1145/3757425\", \"link_to_user\": \"\u7ed3\u6784\u5316\u610f\u4e49\u5efa\u6784 \u2192 \u89c2\u4f17\u5bf9\u6587\u7269\u7684\u7406\u89e3\u8fc7\u7a0b\uff08\u5f31\u5173\u8054\uff09\", \"title_zh\": \"SnuggleSense\uff1a\u901a\u8fc7\u7ed3\u6784\u5316\u610f\u4e49\u5efa\u6784\u8fc7\u7a0b\u8d4b\u80fd\u7f51\u7edc\u4f24\u5bb3\u5e78\u5b58\u8005\"}], \"evidence_projects_funding\": \"\u4e2a\u4eba\u4e3b\u9875/CV\uff1a2026 \u5e74 11 \u6708\u8d77\u4efb\u7ef4\u4e5f\u7eb3\u5927\u5b66\u8ba1\u7b97\u673a\u5b66\u9662 HCI \u52a9\u7406\u6559\u6388\uff0c\u73b0\u4e3a CMU HCII \u535a\u58eb\u540e\uff1bDoCS \u79cb\u5b63\u6279\u6b21\u62db 1 \u540d\u535a\u58eb\uff08\u622a\u6b62 2026-10-15\uff0c2027-03-01 \u5165\u5b66\uff0c\u5168\u989d\u8d44\u52a9\uff09\uff0c\u5c97\u4f4d\u5199\u660e\u63a5\u53d7 CS\u3001HCI\u3001\u8bbe\u8ba1\u3001\u793e\u4f1a\u79d1\u5b66\u7855\u58eb\u3002\", \"fit_to_user\": \"\u5c97\u4f4d\u660e\u786e\u63a5\u53d7\u8bbe\u8ba1\u80cc\u666f\uff1b\u65b0\u7ec4 PI \u6295\u5165\u65f6\u95f4\u591a\uff1b\u82e5\u9898\u76ee\u6539\u4e3a'\u751f\u6210\u5f0f AI \u5728\u6587\u5316\u9057\u4ea7\u5448\u73b0\u4e2d\u7684\u4f24\u5bb3\u4e0e\u95ee\u8d23'\u53ef\u52c9\u5f3a\u5bf9\u63a5\u3002\", \"counterargument_risk\": \"\u7814\u7a76\u65b9\u5411\uff08\u8d1f\u8d23\u4efb AI\u3001\u7f51\u7edc\u4f24\u5bb3\u3001\u793e\u4f1a\u8ba1\u7b97\uff09\u4e0e\u624b\u52bf/\u7167\u660e/XR \u51e0\u4e4e\u65e0\u4ea4\u96c6\uff0c\u76f8\u5173\u5ea6 3\uff1b\u622a\u6b62 2026-10-15 \u4ec5\u5269 6 \u5929\uff1b\u65b0\u4efb\u52a9\u7406\u6559\u6388\u5728\u5965\u5730\u5229\u80fd\u5426\u72ec\u7acb\u6307\u5bfc\u9700\u770b DoCS \u89c4\u5219\u3002\", \"email_hook\": \"Your Vipera work on auditing text-to-image models raises a question I face in heritage: who checks how generative AI depicts cultural artefacts?\", \"sources\": [\"https://www.applexiao.com/\", \"http://applexiao.com/cv.pdf\", \"https://app.resumeset.com/jobs/univie-doctoral-school-computer-science-docs-doctoral-positions-autumn-call-2026-176611/\", \"https://orcid.org/0009-0004-5889-1376\"], \"verified\": false, \"csc_note\": \"\u5c97\u4f4d\u5236\uff1aUniVie DoCS 2026 \u79cb\u5b63\u6279\u6b21\u535a\u58eb\u804c\u4f4d\uff08Job ID 6163\uff09\uff0c\u622a\u6b62 2026-10-15 14:00 CET\uff0c2027-03-01 \u5165\u5b66\uff0c\u6709\u5168\u989d\u8d44\u52a9\u3002\", \"matched_keywords\": [\"HCI\", \"responsible AI\", \"social computing\"], \"csc_status\": \"unknown\", \"in_user_csc_list\": false, \"email_draft\": {\"to\": null, \"subject\": \"DoCS Job ID 6163: responsible generative AI in cultural heritage presentation\", \"body\": \"Dear Professor Xiao,\\n\\nYour CHI 2026 paper on Vipera, a system for auditing text-to-image models, raises a question I meet in heritage work: who checks how generative AI depicts cultural artefacts and traditions? I would like to apply for a PhD through the UniVie Doctoral School Computer Science position in HCI, Responsible AI and Social Computing (Job ID 6163).\\n\\nSince November 2025 I have directed the Digital ICH Design and Production Teaching and Research Office at Quanzhou Huaguang College, teaching 3D character design, digital sculpting and cultural-product design, supervising student 3D content production and leading a VR collaborative lighting design project (JAT251371). Previously, as a lighting hardware product manager, I ran nine product families at OSRAM/LEDVANCE (~100 SKUs, ~US$8M in sales), including light-distribution analysis for Abu Dhabi's Zayed Airport, and led user research (Amazon data, DEMATEL) at LEEDARSON for smart-lighting lines selling over US$30M. My office's heritage team and students could take part in audits.\\n\\nMy most relevant prototype is Stone Reveal (https://cooleli.github.io/Portfolio-page/Dunhuang%20Interactive%20Heritage%20project/): four Dunhuang Buddha figures as Three.js particle clouds; with in-browser MediaPipe hand tracking, visitors brush away the \\\"dust\\\" and join palms to reveal the gilded figure. A companion project does this for Chinese bronzes.\\n\\nFor a PhD I would like to study how generative and interactive AI shapes the presentation of cultural heritage \u2014 where it misrepresents traditions, how communities and curators could audit and contest it, and how interactive installations can make such uncertainty visible to visitors.\\n\\nTo be direct: my degrees are in design, not computer science, and I have no first-author paper yet (two co-authored MR papers). I bring working prototypes, a granted MR invention patent and a practice-based approach I would turn into peer-reviewed studies early.\\n\\nI know my prototypes focus on gesture and XR rather than social computing, so I would value your honest view on fit before the 15 October deadline. Would you be open to supervising this topic? I would be glad to send a two-page proposal.\\n\\nBest regards,\\nHanlei (Eli) Zeng\\nDirector, Digital ICH Design & Production Teaching and Research Office, Quanzhou Huaguang College, China\\nPortfolio & CV: https://cooleli.github.io/CV-project/v2/\", \"note_zh\": \"\u5207\u5165\u70b9\uff1aVipera \u751f\u6210\u5f0f\u56fe\u50cf\u5ba1\u8ba1 \u2192 \u6587\u5316\u9057\u4ea7\u88ab AI \u8bef\u8bfb\u7684\u95ee\u9898\u3002\u53d1\u9001\u524d\u786e\u8ba4\uff1a\u622a\u6b62 2026-10-15 14:00 CET\uff08\u4ec5\u5269\u7ea6 6 \u5929\uff09\uff0c\u82e5\u6295\u987b\u7acb\u5373\u51c6\u5907\uff1b\u76f8\u5173\u5ea6\u4ec5 3 \u5206\uff0c\u53ef\u80fd\u4e0d\u503c\u5f97\uff1b\u5b98\u65b9 univie \u90ae\u7bb1\u672a\u5728\u5b98\u65b9\u9875\u516c\u5f00\uff08\u5176 LinkedIn \u5e16\u5199 sijia.xiao@cs.univie.ac.at\uff0c\u4e2a\u4eba\u4e3b\u9875\u4e3a CMU \u90ae\u7bb1\uff09\uff0cto_email \u9700\u786e\u8ba4\u540e\u518d\u586b\u3002\", \"subject_zh\": \"DoCS \u5c97\u4f4d\u7f16\u53f7 6163\uff1a\u6587\u5316\u9057\u4ea7\u5448\u73b0\u4e2d\u8d1f\u8d23\u4efb\u7684\u751f\u6210\u5f0f AI\", \"body_zh\": \"\u5c0a\u656c\u7684 Xiao \u6559\u6388\uff1a\\n\\n\u60a8\u5728 CHI 2026 \u4e0a\u5173\u4e8e Vipera\uff08\u4e00\u4e2a\u5ba1\u8ba1\u6587\u751f\u56fe\u6a21\u578b\u7684\u7cfb\u7edf\uff09\u7684\u8bba\u6587\uff0c\u63d0\u51fa\u4e86\u4e00\u4e2a\u6211\u5728\u9057\u4ea7\u5de5\u4f5c\u4e2d\u9047\u5230\u7684\u95ee\u9898\uff1a\u8c01\u6765\u6838\u67e5\u751f\u6210\u5f0f AI \u5982\u4f55\u63cf\u7ed8\u6587\u7269\u4e0e\u4f20\u7edf\uff1f\u6211\u5e0c\u671b\u901a\u8fc7\u7ef4\u4e5f\u7eb3\u5927\u5b66\u8ba1\u7b97\u673a\u79d1\u5b66\u535a\u58eb\u751f\u9662\u201c\u4eba\u673a\u4ea4\u4e92\u3001\u8d1f\u8d23\u4efb\u7684 AI \u4e0e\u793e\u4f1a\u8ba1\u7b97\u201d\u5c97\u4f4d\uff08\u5c97\u4f4d\u7f16\u53f7 6163\uff09\u7533\u8bf7\u535a\u58eb\u3002\\n\\n\u81ea 2025 \u5e74 11 \u6708\u8d77\uff0c\u6211\u62c5\u4efb\u6cc9\u5dde\u534e\u5149\u804c\u4e1a\u5b66\u9662\u6570\u5b57\u975e\u9057\u8bbe\u8ba1\u4e0e\u5236\u4f5c\u6559\u7814\u5ba4\u4e3b\u4efb\uff0c\u4e3b\u8bb2 3D \u89d2\u8272\u8bbe\u8ba1\u3001\u6570\u5b57\u96d5\u523b\u4e0e\u6587\u521b\u4ea7\u54c1\u8bbe\u8ba1\uff0c\u6307\u5bfc\u5b66\u751f\u7684 3D \u5185\u5bb9\u751f\u4ea7\uff0c\u5e76\u4e3b\u6301\u4e00\u9879 VR \u534f\u540c\u7167\u660e\u8bbe\u8ba1\u7814\u7a76\u9879\u76ee\uff08JAT251371\uff09\u3002\u6b64\u524d\u6211\u662f\u7167\u660e\u786c\u4ef6\u4ea7\u54c1\u7ecf\u7406\uff1a\u5728 OSRAM/LEDVANCE\uff08\u6b27\u53f8\u6717/\u6717\u5fb7\u4e07\u65af\uff09\u8d1f\u8d23 9 \u4e2a\u4ea7\u54c1\u7cfb\u5217\uff08\u7ea6 100 \u4e2a SKU\uff0c\u7d2f\u8ba1\u9500\u552e\u7ea6 800 \u4e07\u7f8e\u5143\uff09\uff0c\u5176\u4e2d\u5305\u62ec\u4e3a\u963f\u5e03\u624e\u6bd4 Zayed \u673a\u573a\u9879\u76ee\u505a\u914d\u5149\u5206\u6790\uff1b\u5728 LEEDARSON\uff08\u7acb\u8fbe\u4fe1\uff09\u4e3b\u5bfc\u667a\u80fd\u7167\u660e\u4ea7\u54c1\u7ebf\u7684\u7528\u6237\u7814\u7a76\uff08\u4e9a\u9a6c\u900a\u6570\u636e\u3001DEMATEL\uff09\uff0c\u8fd9\u4e9b\u4ea7\u54c1\u7ebf\u7d2f\u8ba1\u9500\u552e\u8d85\u8fc7 3000 \u4e07\u7f8e\u5143\u3002\u6211\u6559\u7814\u5ba4\u7684\u975e\u9057\u56e2\u961f\u548c\u5b66\u751f\u4e5f\u53ef\u4ee5\u53c2\u4e0e\u6b64\u7c7b\u5ba1\u8ba1\u3002\\n\\n\u4e0e\u6b64\u6700\u76f8\u5173\u7684\u539f\u578b\u662f Stone Reveal\uff08\u300a\u77f3\u50cf\u663e\u73b0\u300b\uff09\uff08https://cooleli.github.io/Portfolio-page/Dunhuang%20Interactive%20Heritage%20project/\uff09\uff1a\u56db\u5c0a\u6566\u714c\u4f5b\u50cf\u88ab\u505a\u6210 Three.js \u7c92\u5b50\u4e91\uff1b\u501f\u52a9\u6d4f\u89c8\u5668\u5185\u7684 MediaPipe \u624b\u90e8\u8ffd\u8e2a\uff0c\u89c2\u4f17\u62c2\u53bb\u201c\u5c18\u571f\u201d\uff0c\u53cc\u624b\u5408\u5341\u5373\u53ef\u663e\u73b0\u938f\u91d1\u4f5b\u8eab\u3002\u53e6\u4e00\u4e2a\u914d\u5957\u9879\u76ee\u4ee5\u540c\u6837\u65b9\u5f0f\u5448\u73b0\u4e2d\u56fd\u9752\u94dc\u5668\u3002\\n\\n\u5728\u535a\u58eb\u9636\u6bb5\uff0c\u6211\u5e0c\u671b\u7814\u7a76\u751f\u6210\u5f0f\u4e0e\u4ea4\u4e92\u5f0f AI \u5982\u4f55\u5851\u9020\u6587\u5316\u9057\u4ea7\u7684\u5448\u73b0\u2014\u2014\u5b83\u5728\u54ea\u4e9b\u5730\u65b9\u8bef\u8bfb\u4e86\u4f20\u7edf\uff0c\u793e\u7fa4\u548c\u7b56\u5c55\u4eba\u5982\u4f55\u5ba1\u8ba1\u5e76\u8d28\u7591\u5b83\uff0c\u4ee5\u53ca\u4e92\u52a8\u88c5\u7f6e\u5982\u4f55\u8ba9\u89c2\u4f17\u770b\u89c1\u8fd9\u79cd\u4e0d\u786e\u5b9a\u6027\u3002\\n\\n\u5766\u767d\u5730\u8bf4\uff1a\u6211\u7684\u5b66\u4f4d\u662f\u8bbe\u8ba1\u5b66\u800c\u975e\u8ba1\u7b97\u673a\u79d1\u5b66\uff0c\u76ee\u524d\u8fd8\u6ca1\u6709\u7b2c\u4e00\u4f5c\u8005\u8bba\u6587\uff08\u6709\u4e24\u7bc7\u5408\u8457\u7684 MR \u8bba\u6587\uff09\u3002\u6211\u80fd\u5e26\u6765\u7684\u662f\u53ef\u8fd0\u884c\u7684\u539f\u578b\u3001\u4e00\u9879 MR \u9886\u57df\u7684\u5df2\u6388\u6743\u53d1\u660e\u4e13\u5229\uff0c\u4ee5\u53ca\u4e00\u5957\u5b9e\u8df5\u578b\u7814\u7a76\u65b9\u6cd5\uff0c\u6211\u4f1a\u5728\u65e9\u671f\u5c31\u628a\u5b83\u8f6c\u5316\u4e3a\u7ecf\u540c\u884c\u8bc4\u5ba1\u7684\u7814\u7a76\u3002\\n\\n\u6211\u77e5\u9053\u6211\u7684\u539f\u578b\u4fa7\u91cd\u4e8e\u624b\u52bf\u548c XR \u800c\u975e\u793e\u4f1a\u8ba1\u7b97\uff0c\u56e0\u6b64\u5e0c\u671b\u5728 10 \u6708 15 \u65e5\u622a\u6b62\u65e5\u671f\u524d\u542c\u5230\u60a8\u5bf9\u5951\u5408\u5ea6\u7684\u5766\u8bda\u770b\u6cd5\u3002\u8bf7\u95ee\u60a8\u662f\u5426\u613f\u610f\u6307\u5bfc\u8fd9\u4e00\u8bfe\u9898\uff1f\u6211\u5f88\u4e50\u610f\u5bc4\u4e0a\u4e00\u4efd\u4e24\u9875\u7684\u7814\u7a76\u8ba1\u5212\u3002\\n\\n\u6b64\u81f4\\n\u656c\u793c\\nHanlei (Eli) Zeng\uff08\u66fe\u97e9\u64c2\uff09\\n\u4e2d\u56fd\u6cc9\u5dde\u534e\u5149\u804c\u4e1a\u5b66\u9662 \u6570\u5b57\u975e\u9057\u8bbe\u8ba1\u4e0e\u5236\u4f5c\u6559\u7814\u5ba4\u4e3b\u4efb\\n\u4f5c\u54c1\u96c6\u4e0e\u7b80\u5386\uff1ahttps://cooleli.github.io/CV-project/v2/\"}, \"phd_students\": {\"found\": false, \"students\": [], \"total_estimate\": \"0\uff082026 \u5e74 11 \u6708\u624d\u5165\u804c\u7ef4\u4e5f\u7eb3\u5927\u5b66\u4efb HCI \u52a9\u7406\u6559\u6388\uff0c\u6b63\u5728\u62db\u6536\u9996\u6279\u535a\u58eb\u751f\uff09\", \"student_pattern_zh\": \"\u5c1a\u65e0\u535a\u58eb\u751f\u3002\u672c\u4eba\u65b9\u5411\uff1a\u793e\u4f1a\u8ba1\u7b97\u3001\u8d1f\u8d23\u4efb AI\u3001\u6280\u672f\u4f24\u5bb3\u7684\u610f\u4e49\u5efa\u6784\u4e0e\u4fee\u590d\uff1b\u65b9\u6cd5\u4e3a\u8d28\u6027\u8bbf\u8c08\u3001\u53c2\u4e0e\u5f0f\u8bbe\u8ba1\u3001\u5b9e\u9a8c\u4e0e\u7cfb\u7edf\u6784\u5efa\u3002\", \"design_background_ok_zh\": \"\u65e0\u5b66\u751f\u8bc1\u636e\uff1b\u5176\u65b9\u6cd5\u504f\u8d28\u6027\u4e0e\u53c2\u4e0e\u5f0f\u8bbe\u8ba1\uff0c\u5bf9\u975e CS \u80cc\u666f\u7406\u8bba\u4e0a\u53cb\u597d\u3002\", \"chinese_students_zh\": \"\u672c\u4eba\u5317\u4eac\u5927\u5b66\u8ba1\u7b97\u673a\u672c\u79d1\u3001\u4f50\u6cbb\u4e9a\u7406\u5de5 HCI \u7855\u58eb\u3001UC Berkeley \u535a\u58eb\uff1b\u5c1a\u65e0\u5b66\u751f\u3002\", \"implication_zh\": \"\u65b0\u664b\u5bfc\u5e08\u62db\u751f\u610f\u613f\u5f3a\u3001\u53ef\u6c9f\u901a\u4e2d\u6587\uff1b\u4f46\u7814\u7a76\u65b9\u5411\uff08\u5728\u7ebf\u4f24\u5bb3\u3001\u8d1f\u8d23\u4efb AI\uff09\u4e0e\u7528\u6237\u7684\u5177\u8eab\u4ea4\u4e92/\u6570\u5b57\u9057\u4ea7\u5dee\u8ddd\u5927\uff0c\u9664\u975e\u8f6c\u5411\u201c\u6587\u5316\u9057\u4ea7\u4e2d\u7684 AI \u4f26\u7406/\u793e\u533a\u53c2\u4e0e\u201d\uff0c\u5426\u5219\u4e0d\u5efa\u8bae\u4f5c\u4e3a\u4e3b\u653b\u3002\", \"sources\": [\"https://www.applexiao.com/\"], \"searched\": [\"\u4e2a\u4eba\u4e3b\u9875\uff08News\u3001Advising & Hiring \u94fe\u63a5\uff09\", \"ORCID/CV \u672a\u53d1\u73b0\u5b66\u751f\"]}, \"title_zh\": \"\u4eba\u673a\u4ea4\u4e92\u52a9\u7406\u6559\u6388\uff082026 \u5e74 11 \u6708\u8d77\uff09\", \"unit_zh\": \"\u534f\u4f5c\u7cfb\u7edf\uff0c\u7ef4\u4e5f\u7eb3\u5927\u5b66\u8ba1\u7b97\u673a\u79d1\u5b66\u5b66\u9662\", \"email_hook_zh\": \"\u60a8\u5728 Vipera \u4e2d\u5ba1\u67e5\u6587\u751f\u56fe\u6a21\u578b\u7684\u7814\u7a76\uff0c\u63d0\u51fa\u4e86\u4e00\u4e2a\u6211\u5728\u9057\u4ea7\u9886\u57df\u540c\u6837\u9762\u4e34\u7684\u95ee\u9898\uff1a\u7531\u8c01\u6765\u68c0\u67e5\u751f\u6210\u5f0f AI \u5982\u4f55\u63cf\u7ed8\u6587\u5316\u6587\u7269\uff1f\", \"csc_status_zh\": \"\u672a\u77e5\"}, {\"name\": \"Caroline Sporleder\", \"school_en\": \"University of G\u00f6ttingen\", \"school_zh\": \"\u54e5\u5ef7\u6839\u5927\u5b66\", \"country\": \"\", \"title\": \"Professor for Digital Humanities; Executive Director, G\u00f6ttingen Centre for Digital Humanities (GCDH)\", \"unit\": \"Institute of Computer Science / Institute for Digital Humanities, University of G\u00f6ttingen\", \"homepage\": \"https://www.uni-goettingen.de/de/597865.html\", \"email\": null, \"relevance\": 3, \"claim\": \"Sporleder \u662f\u54e5\u5ef7\u6839\u6570\u5b57\u4eba\u6587\u6559\u6388\u3001GCDH \u6267\u884c\u4e3b\u4efb\uff0c\u65b9\u5411\u4e3a\u8ba1\u7b97\u8bed\u8a00\u5b66\u4e0e\u591a\u6a21\u6001\u5206\u6790\uff1b\u5979\u662f\u54e5\u5ef7\u6839\u6570\u5b57\u4eba\u6587\u4f53\u7cfb\u7684\u6838\u5fc3\uff0c\u4f46\u4e0e\u7528\u6237\u4ea4\u4e92/\u89c6\u89c9\u65b9\u5411\u76f8\u5173\u5ea6\u4f4e\uff0c\u4ec5\u4f5c\u653e\u5bbd\u5230'\u6570\u5b57\u4eba\u6587'\u540e\u7684\u5019\u9009\u3002\", \"evidence_homepage\": \"https://www.uni-goettingen.de/de/597865.html\", \"evidence_papers\": [{\"title\": \"Modelling Speaker Attribution in Narrative Texts With Biased and Bias-Adjustable Neural Networks\", \"year\": 2022, \"venue\": \"Frontiers in Artificial Intelligence\", \"url\": \"https://doi.org/10.3389/frai.2021.725321\", \"link_to_user\": \"\u53d9\u4e8b\u6587\u672c\u8ba1\u7b97\u5206\u6790 \u2192 \u6587\u7269\u53d9\u4e8b\u811a\u672c\uff08\u5f31\u5173\u8054\uff09\", \"title_zh\": \"\u7528\u6709\u504f\u4e0e\u53ef\u8c03\u504f\u7f6e\u7684\u795e\u7ecf\u7f51\u7edc\u5efa\u6a21\u53d9\u4e8b\u6587\u672c\u4e2d\u7684\u8bf4\u8bdd\u4eba\u5f52\u5c5e\"}, {\"title\": \"Humanities in a Digital World\", \"year\": 2024, \"venue\": \"Edinburgh University Press (book chapter)\", \"url\": \"https://doi.org/10.1515/9781399505208-018\", \"link_to_user\": \"\u6570\u5b57\u4eba\u6587\u7efc\u8ff0 \u2192 \u7528\u6237\u7814\u7a76\u7684\u5b66\u79d1\u5b9a\u4f4d\", \"title_zh\": \"\u6570\u5b57\u4e16\u754c\u4e2d\u7684\u4eba\u6587\u5b66\u79d1\"}, {\"title\": \"Multimodale Sentimentanalyse politischer Tweets\", \"year\": 2019, \"venue\": \"Zenodo (DHd conference abstract)\", \"url\": \"https://doi.org/10.5281/zenodo.4622176\", \"link_to_user\": \"\u6587\u672c+\u56fe\u50cf\u7684\u591a\u6a21\u6001\u5206\u6790 \u2192 \u6587\u7269\u56fe\u6587\u53d9\u4e8b\u7684\u591a\u6a21\u6001\u5448\u73b0\uff08\u5f31\u5173\u8054\uff09\", \"title_zh\": \"\u653f\u6cbb\u63a8\u6587\u7684\u591a\u6a21\u6001\u60c5\u611f\u5206\u6790\"}], \"evidence_projects_funding\": \"\u5b98\u65b9\u7b80\u5386\uff1a2015 \u8d77\u4efb\u54e5\u5ef7\u6839\u5927\u5b66\u4fe1\u606f\u5b66\u9662\u6570\u5b57\u4eba\u6587\u6559\u6388\uff0c\u6b64\u524d\u4e3a\u7279\u91cc\u5c14\u5927\u5b66\u6570\u5b57\u4eba\u6587\u6559\u6388\u3001\u8428\u5c14\u5927\u5b66'\u591a\u6a21\u6001\u8ba1\u7b97\u4e0e\u4ea4\u4e92'\u5353\u8d8a\u96c6\u7fa4\u9752\u5e74\u7ec4\u957f\uff1b\u7814\u7a76\u91cd\u70b9\u5305\u62ec\u591a\u6a21\u6001\u5206\u6790\u3002GCDH \u56e2\u961f\u9875\u5217\u4e3a\u6267\u884c\u4e3b\u4efb\u3002\", \"fit_to_user\": \"\u82e5\u9898\u76ee\u653e\u5bbd\u4e3a'\u975e\u9057/\u6587\u7269\u53d9\u4e8b\u7684\u591a\u6a21\u6001\u6570\u5b57\u4eba\u6587\u5206\u6790'\uff0c\u53ef\u5728 GCDH \u6846\u67b6\u5185\u4e0e Langner \u5408\u4f5c\uff1b\u8428\u5c14\u5927\u5b66\u591a\u6a21\u6001\u4ea4\u4e92\u96c6\u7fa4\u80cc\u666f\u5bf9\u4ea4\u4e92\u6709\u7406\u89e3\u3002\", \"counterargument_risk\": \"\u6838\u5fc3\u662f NLP/\u6587\u672c\uff0c\u51e0\u4e4e\u4e0d\u6d89\u53ca\u89c6\u89c9\u3001XR \u6216\u624b\u52bf\uff1b\u76f8\u5173\u5ea6 3\uff1b\u7528\u6237\u9700\u5927\u5e45\u8c03\u6574\u65b9\u5411\uff0c\u4e0d\u5efa\u8bae\u4f5c\u4e3a\u4e3b\u9009\u3002\", \"email_hook\": \"Your background in the Multimodal Computing and Interaction cluster and your leadership of the G\u00f6ttingen Centre for Digital Humanities make you a natural point of contact for a multimodal heritage project.\", \"sources\": [\"https://www.uni-goettingen.de/de/597865.html\", \"https://www.uni-goettingen.de/en/people/597825.html\", \"https://www.gcdh.de/en/people/team/\", \"https://orcid.org/0000-0002-5912-7028\"], \"verified\": true, \"csc_note\": \"\u54e5\u5ef7\u6839 CSC \u7ebf not_found\uff1b\u53ef\u8d70\u56fd\u5bb6\u516c\u6d3e\\\"\u81ea\u8054\u5bfc\u5e08\\\"\u4e00\u822c\u9879\u76ee\u6216\u5bfc\u5e08\u9879\u76ee\u5c97\u4f4d\u3002\", \"matched_keywords\": [\"digital humanities\", \"multimodal analysis\"], \"csc_status\": \"not_found\", \"in_user_csc_list\": true, \"email_draft\": {\"to\": null, \"subject\": \"PhD enquiry: multimodal digital humanities for gesture-based heritage\", \"body\": \"Dear Professor Sporleder,\\n\\nYour background in the Multimodal Computing and Interaction cluster and your work leading the G\u00f6ttingen Centre for Digital Humanities make you a natural point of contact for a multimodal heritage project. I would like to apply for a PhD at the University of G\u00f6ttingen in digital humanities, possibly co-supervised with Prof. Langner.\\n\\nSince November 2025 I have directed the Digital ICH Design and Production Teaching and Research Office at Quanzhou Huaguang College, teaching 3D character design, digital sculpting and cultural-product design, supervising student 3D content production and leading a VR collaborative lighting design project (JAT251371). Previously, as a lighting hardware product manager, I ran nine product families at OSRAM/LEDVANCE (~100 SKUs, ~US$8M in sales), including light-distribution analysis for Abu Dhabi's Zayed Airport, and led user research (Amazon data, DEMATEL) at LEEDARSON for smart-lighting lines selling over US$30M. My office gives me a heritage digitisation team.\\n\\nMy most relevant prototype is Stone Reveal (https://cooleli.github.io/Portfolio-page/Dunhuang%20Interactive%20Heritage%20project/): four Dunhuang Buddha figures as Three.js particle clouds; with in-browser MediaPipe hand tracking, visitors brush away the \\\"dust\\\" and join palms to reveal the gilded figure. A companion project does this for Chinese bronzes.\\n\\nFor a PhD I would like to study how the narratives attached to heritage objects \u2014 inscriptions, legends, devotional texts \u2014 can be combined with gesture and light in interactive presentations, and how visitors connect what they read, see and do.\\n\\nTo be direct: my degrees are in design, not computer science, and I have no first-author paper yet (two co-authored MR papers). I bring working prototypes, a granted MR invention patent and a practice-based approach I would turn into peer-reviewed studies early.\\n\\nI realise my work is visual and interactive rather than textual, so I would value your frank view on fit. Would you be open to supervising this topic? I would be glad to send a two-page proposal.\\n\\nBest regards,\\nHanlei (Eli) Zeng\\nDirector, Digital ICH Design & Production Teaching and Research Office, Quanzhou Huaguang College, China\\nPortfolio & CV: https://cooleli.github.io/CV-project/v2/\", \"note_zh\": \"\u5207\u5165\u70b9\uff1a\u591a\u6a21\u6001\u4ea4\u4e92\u96c6\u7fa4\u80cc\u666f + GCDH \u4e3b\u4efb\u3002\u53d1\u9001\u524d\u786e\u8ba4\uff1a\u76f8\u5173\u5ea6\u4ec5 3 \u5206\uff0c\u5efa\u8bae\u4ec5\u5728 Langner \u56de\u590d\u79ef\u6781\u65f6\u4f5c\u4e3a\u8054\u5408\u6307\u5bfc\u518d\u8054\u7cfb\uff1b\u90ae\u7bb1\u9700\u5728\u5b98\u65b9\u9875\u70b9\u5f00\u83b7\u53d6\uff08\u672a\u660e\u6587\uff09\uff0cto_email \u5f85\u8865\u3002\", \"subject_zh\": \"\u535a\u58eb\u7533\u8bf7\u54a8\u8be2\uff1a\u9762\u5411\u57fa\u4e8e\u624b\u52bf\u7684\u9057\u4ea7\u7684\u591a\u6a21\u6001\u6570\u5b57\u4eba\u6587\", \"body_zh\": \"\u5c0a\u656c\u7684 Sporleder \u6559\u6388\uff1a\\n\\n\u60a8\u5728\u201c\u591a\u6a21\u6001\u8ba1\u7b97\u4e0e\u4ea4\u4e92\u201d\u5353\u8d8a\u96c6\u7fa4\uff08Multimodal Computing and Interaction\uff09\u7684\u80cc\u666f\uff0c\u4ee5\u53ca\u60a8\u9886\u5bfc\u54e5\u5ef7\u6839\u6570\u5b57\u4eba\u6587\u4e2d\u5fc3\u7684\u5de5\u4f5c\uff0c\u4f7f\u60a8\u6210\u4e3a\u4e00\u4e2a\u591a\u6a21\u6001\u9057\u4ea7\u9879\u76ee\u7684\u5929\u7136\u8054\u7cfb\u4eba\u3002\u6211\u5e0c\u671b\u7533\u8bf7\u54e5\u5ef7\u6839\u5927\u5b66\u6570\u5b57\u4eba\u6587\u65b9\u5411\u7684\u535a\u58eb\uff0c\u6216\u8bb8\u53ef\u7531 Langner \u6559\u6388\u8054\u5408\u6307\u5bfc\u3002\\n\\n\u81ea 2025 \u5e74 11 \u6708\u8d77\uff0c\u6211\u62c5\u4efb\u6cc9\u5dde\u534e\u5149\u804c\u4e1a\u5b66\u9662\u6570\u5b57\u975e\u9057\u8bbe\u8ba1\u4e0e\u5236\u4f5c\u6559\u7814\u5ba4\u4e3b\u4efb\uff0c\u4e3b\u8bb2 3D \u89d2\u8272\u8bbe\u8ba1\u3001\u6570\u5b57\u96d5\u523b\u4e0e\u6587\u521b\u4ea7\u54c1\u8bbe\u8ba1\uff0c\u6307\u5bfc\u5b66\u751f\u7684 3D \u5185\u5bb9\u751f\u4ea7\uff0c\u5e76\u4e3b\u6301\u4e00\u9879 VR \u534f\u540c\u7167\u660e\u8bbe\u8ba1\u7814\u7a76\u9879\u76ee\uff08JAT251371\uff09\u3002\u6b64\u524d\u6211\u662f\u7167\u660e\u786c\u4ef6\u4ea7\u54c1\u7ecf\u7406\uff1a\u5728 OSRAM/LEDVANCE\uff08\u6b27\u53f8\u6717/\u6717\u5fb7\u4e07\u65af\uff09\u8d1f\u8d23 9 \u4e2a\u4ea7\u54c1\u7cfb\u5217\uff08\u7ea6 100 \u4e2a SKU\uff0c\u7d2f\u8ba1\u9500\u552e\u7ea6 800 \u4e07\u7f8e\u5143\uff09\uff0c\u5176\u4e2d\u5305\u62ec\u4e3a\u963f\u5e03\u624e\u6bd4 Zayed \u673a\u573a\u9879\u76ee\u505a\u914d\u5149\u5206\u6790\uff1b\u5728 LEEDARSON\uff08\u7acb\u8fbe\u4fe1\uff09\u4e3b\u5bfc\u667a\u80fd\u7167\u660e\u4ea7\u54c1\u7ebf\u7684\u7528\u6237\u7814\u7a76\uff08\u4e9a\u9a6c\u900a\u6570\u636e\u3001DEMATEL\uff09\uff0c\u8fd9\u4e9b\u4ea7\u54c1\u7ebf\u7d2f\u8ba1\u9500\u552e\u8d85\u8fc7 3000 \u4e07\u7f8e\u5143\u3002\u6211\u7684\u6559\u7814\u5ba4\u4e5f\u4e3a\u6211\u63d0\u4f9b\u4e86\u4e00\u652f\u975e\u9057\u6570\u5b57\u5316\u56e2\u961f\u3002\\n\\n\u4e0e\u6b64\u6700\u76f8\u5173\u7684\u539f\u578b\u662f Stone Reveal\uff08\u300a\u77f3\u50cf\u663e\u73b0\u300b\uff09\uff08https://cooleli.github.io/Portfolio-page/Dunhuang%20Interactive%20Heritage%20project/\uff09\uff1a\u56db\u5c0a\u6566\u714c\u4f5b\u50cf\u88ab\u505a\u6210 Three.js \u7c92\u5b50\u4e91\uff1b\u501f\u52a9\u6d4f\u89c8\u5668\u5185\u7684 MediaPipe \u624b\u90e8\u8ffd\u8e2a\uff0c\u89c2\u4f17\u62c2\u53bb\u201c\u5c18\u571f\u201d\uff0c\u53cc\u624b\u5408\u5341\u5373\u53ef\u663e\u73b0\u938f\u91d1\u4f5b\u8eab\u3002\u53e6\u4e00\u4e2a\u914d\u5957\u9879\u76ee\u4ee5\u540c\u6837\u65b9\u5f0f\u5448\u73b0\u4e2d\u56fd\u9752\u94dc\u5668\u3002\\n\\n\u5728\u535a\u58eb\u9636\u6bb5\uff0c\u6211\u5e0c\u671b\u7814\u7a76\u9057\u4ea7\u5668\u7269\u6240\u9644\u5e26\u7684\u53d9\u4e8b\u2014\u2014\u94ed\u6587\u3001\u4f20\u8bf4\u3001\u793c\u4f5b\u6587\u672c\u2014\u2014\u5982\u4f55\u5728\u4e92\u52a8\u5448\u73b0\u4e2d\u4e0e\u624b\u52bf\u548c\u5149\u76f8\u7ed3\u5408\uff0c\u4ee5\u53ca\u89c2\u4f17\u5982\u4f55\u628a\u4ed6\u4eec\u8bfb\u5230\u7684\u3001\u770b\u5230\u7684\u548c\u505a\u7684\u8054\u7cfb\u8d77\u6765\u3002\\n\\n\u5766\u767d\u5730\u8bf4\uff1a\u6211\u7684\u5b66\u4f4d\u662f\u8bbe\u8ba1\u5b66\u800c\u975e\u8ba1\u7b97\u673a\u79d1\u5b66\uff0c\u76ee\u524d\u8fd8\u6ca1\u6709\u7b2c\u4e00\u4f5c\u8005\u8bba\u6587\uff08\u6709\u4e24\u7bc7\u5408\u8457\u7684 MR \u8bba\u6587\uff09\u3002\u6211\u80fd\u5e26\u6765\u7684\u662f\u53ef\u8fd0\u884c\u7684\u539f\u578b\u3001\u4e00\u9879 MR \u9886\u57df\u7684\u5df2\u6388\u6743\u53d1\u660e\u4e13\u5229\uff0c\u4ee5\u53ca\u4e00\u5957\u5b9e\u8df5\u578b\u7814\u7a76\u65b9\u6cd5\uff0c\u6211\u4f1a\u5728\u65e9\u671f\u5c31\u628a\u5b83\u8f6c\u5316\u4e3a\u7ecf\u540c\u884c\u8bc4\u5ba1\u7684\u7814\u7a76\u3002\\n\\n\u6211\u610f\u8bc6\u5230\u6211\u7684\u5de5\u4f5c\u4ee5\u89c6\u89c9\u548c\u4ea4\u4e92\u4e3a\u4e3b\u800c\u975e\u6587\u672c\uff0c\u56e0\u6b64\u975e\u5e38\u5e0c\u671b\u542c\u5230\u60a8\u5bf9\u5951\u5408\u5ea6\u7684\u5766\u7387\u770b\u6cd5\u3002\u8bf7\u95ee\u60a8\u662f\u5426\u613f\u610f\u6307\u5bfc\u8fd9\u4e00\u8bfe\u9898\uff1f\u6211\u5f88\u4e50\u610f\u5bc4\u4e0a\u4e00\u4efd\u4e24\u9875\u7684\u7814\u7a76\u8ba1\u5212\u3002\\n\\n\u6b64\u81f4\\n\u656c\u793c\\nHanlei (Eli) Zeng\uff08\u66fe\u97e9\u64c2\uff09\\n\u4e2d\u56fd\u6cc9\u5dde\u534e\u5149\u804c\u4e1a\u5b66\u9662 \u6570\u5b57\u975e\u9057\u8bbe\u8ba1\u4e0e\u5236\u4f5c\u6559\u7814\u5ba4\u4e3b\u4efb\\n\u4f5c\u54c1\u96c6\u4e0e\u7b80\u5386\uff1ahttps://cooleli.github.io/CV-project/v2/\"}, \"phd_students\": {\"found\": true, \"students\": [{\"name\": \"Franziska Pannach\", \"status\": \"alumni\", \"graduation_year\": 2023, \"thesis_title\": \"Narrative Echoes across Time and Space: Comparative Analysis of Structural Similarities in Myth and Folktale Sequences\", \"topic_zh\": \"\u8de8\u65f6\u7a7a\u7684\u53d9\u4e8b\u56de\u58f0\uff1a\u795e\u8bdd\u4e0e\u6c11\u95f4\u6545\u4e8b\u5e8f\u5217\u7ed3\u6784\u76f8\u4f3c\u6027\u6bd4\u8f83\uff08Sporleder \u4e3a Referentin\uff09\", \"url\": \"https://hylistics.uni-goettingen.de/wp-content/uploads/Pannach-2024-Narrative-Echoes-across-Time-and-Space_PhD-thesis-Uni-Goett-2023.pdf\", \"now\": null, \"background\": \"\u7855\u58eb\uff1a\u57fa\u4e8e Propp \u5f62\u6001\u5b66\u7684\u5357\u90e8\u975e\u6d32\u6c11\u95f4\u6545\u4e8b\u672c\u4f53\u7cfb\u7edf\", \"chinese_or_csc\": null}, {\"name\": \"Mariona Coll Ardanuy\", \"status\": \"alumni\", \"graduation_year\": 2017, \"thesis_title\": \"Entity-Centric Text Mining for Historical Documents\", \"topic_zh\": \"\u9762\u5411\u5386\u53f2\u6587\u732e\u7684\u5b9e\u4f53\u4e2d\u5fc3\u6587\u672c\u6316\u6398\", \"url\": \"https://d-nb.info/1144654424/34\", \"now\": null, \"background\": null, \"chinese_or_csc\": null}, {\"name\": \"Stefan Ziehe\", \"status\": \"current\", \"start_year\": null, \"research_topic\": \"(PhD student at GCDH; topic not stated \u2014 MSc on multimodal sentiment analysis)\", \"topic_zh\": \"GCDH \u535a\u58eb\u751f\uff08\u9898\u76ee\u672a\u5217\uff1b\u7855\u58eb\u4e3a\u591a\u6a21\u6001\u60c5\u611f\u5206\u6790\uff09\", \"url\": \"https://www.gcdh.de/en/people/team\", \"now\": null, \"background\": null, \"chinese_or_csc\": null}], \"total_estimate\": \"\u5df2\u6bd5\u4e1a 2\uff082017\u30012023\uff09/ \u5728\u8bfb\u7ea6 1\u20132\uff08GCDH \u56e2\u961f\u9875\uff09\uff1b\u53e6\u4e0e Langner \u8054\u5408\u6307\u5bfc\u7855\u58eb\", \"student_pattern_zh\": \"\u8ba1\u7b97\u8bed\u8a00\u5b66 \u00d7 \u4eba\u6587\uff1a\u6c11\u95f4\u6545\u4e8b/\u795e\u8bdd\u53d9\u4e8b\u7ed3\u6784\u3001\u5386\u53f2\u6587\u732e\u6587\u672c\u6316\u6398\u3001\u591a\u6a21\u6001\u60c5\u611f\uff1b\u65b9\u6cd5\u4e3a NLP/\u8ba1\u7b97\u578b\u3002\", \"design_background_ok_zh\": \"\u65e0\u8bbe\u8ba1\u80cc\u666f\u8bc1\u636e\uff1b\u5b66\u751f\u4e3a\u8ba1\u7b97\u673a/\u8bed\u8a00\u5b66\u80cc\u666f\u3002\", \"chinese_students_zh\": \"\u672a\u53d1\u73b0\u4e2d\u56fd\u5b66\u751f/CSC \u8bc1\u636e\u3002\", \"implication_zh\": \"Pannach \u7684\u201c\u6c11\u95f4\u6545\u4e8b/\u795e\u8bdd\u53d9\u4e8b\u7ed3\u6784\u201d\u4e0e\u975e\u9057\u53d9\u4e8b\u6709\u6982\u5ff5\u4ea4\u96c6\uff0c\u53ef\u4f5c\u4e3a\u201c\u975e\u9057\u53d9\u4e8b\u6570\u636e\u9a71\u52a8\u53d9\u4e8b\u7167\u660e\u201d\u7684\u8ba1\u7b97\u4fa7\uff1b\u4f46\u5979\u662f NLP \u5b66\u8005\uff0c\u4e0e\u4ea4\u4e92/\u7167\u660e\u8bbe\u8ba1\u8ddd\u79bb\u8fdc\uff0c\u4ec5\u9002\u5408\u4f5c\u4e3a\u7b2c\u4e8c\u5bfc\u5e08\u3002\", \"sources\": [\"https://glad.uni-goettingen.de/en/graduation+projects/597860.html\", \"https://hylistics.uni-goettingen.de/wp-content/uploads/Pannach-2024-Narrative-Echoes-across-Time-and-Space_PhD-thesis-Uni-Goett-2023.pdf\", \"https://d-nb.info/1144654424/34\", \"https://www.gcdh.de/en/people/team\"], \"searched\": [\"\u54e5\u5ef7\u6839\u6570\u5b57\u4eba\u6587\u7814\u7a76\u6240 PhD Projects \u9875\", \"\u8bba\u6587\u5c01\u9762/\u81f4\u8c22\", \"GCDH \u56e2\u961f\u9875\", \"DNB\", \"Google \u641c\u7d22\"]}, \"title_zh\": \"\u6570\u5b57\u4eba\u6587\u6559\u6388\uff1b\u54e5\u5ef7\u6839\u6570\u5b57\u4eba\u6587\u4e2d\u5fc3\uff08GCDH\uff09\u6267\u884c\u4e3b\u4efb\", \"unit_zh\": \"\u54e5\u5ef7\u6839\u5927\u5b66\u8ba1\u7b97\u673a\u79d1\u5b66\u7814\u7a76\u6240 / \u6570\u5b57\u4eba\u6587\u7814\u7a76\u6240\", \"email_hook_zh\": \"\u60a8\u5728\u591a\u6a21\u6001\u8ba1\u7b97\u4e0e\u4ea4\u4e92\u96c6\u7fa4\uff08Multimodal Computing and Interaction cluster\uff09\u7684\u80cc\u666f\uff0c\u4ee5\u53ca\u60a8\u5bf9\u54e5\u5ef7\u6839\u6570\u5b57\u4eba\u6587\u4e2d\u5fc3\u7684\u9886\u5bfc\uff0c\u4f7f\u60a8\u81ea\u7136\u6210\u4e3a\u591a\u6a21\u6001\u9057\u4ea7\u9879\u76ee\u7684\u5408\u9002\u8054\u7cfb\u4eba\u3002\", \"csc_status_zh\": \"\u672a\u627e\u5230\"}, {\"name\": \"Prof. C\u00e9cile M\u00e9adel\", \"school_en\": \"Universit\u00e9 Paris-Panth\u00e9on-Assas (Paris II)\", \"school_zh\": \"\u5df4\u9ece\u7b2c\u4e8c\u5927\u5b66\", \"country\": \"\", \"title\": \"Professeure des universit\u00e9s (Sciences de l'information et de la communication); Directrice du CARISM; Vice-pr\u00e9sidente num\u00e9rique\", \"unit\": \"Institut fran\u00e7ais de presse (IFP) / CARISM (EA 2293), Universit\u00e9 Paris-Panth\u00e9on-Assas\", \"homepage\": \"https://www.assas-universite.fr/fr/universite/contacts/enseignants-chercheurs/mme-cecile-meadel\", \"email\": \"cecile.meadel@u-paris2.fr\", \"relevance\": 3, \"claim\": \"M\u00e9adel \u662f Assas \u552f\u4e00\u53ef\u4f5c\u4e3a\u535a\u58eb\u4e3b\u5bfc\u5e08\uff08\u6559\u6388\u3001CARISM \u4e3b\u4efb\uff09\u4e14\u8fd1\u5e74\u4e13\u95e8\u7814\u7a76\u5143\u5b87\u5b99/\u6c89\u6d78\u5f0f\u6280\u672f\u4ea7\u4e1a\u4e0e\u4f7f\u7528\u7684\u5b66\u8005\uff1b\u4f46\u5979\u505a\u7684\u662f\u4f20\u64ad\u793e\u4f1a\u5b66\uff0c\u4e0d\u505a\u4ea4\u4e92\u8bbe\u8ba1\u6216\u539f\u578b\u3002\", \"evidence_homepage\": \"https://www.assas-universite.fr/fr/universite/contacts/enseignants-chercheurs/mme-cecile-meadel\", \"evidence_papers\": [{\"title\": \"La technologie est-elle soluble dans les podcasts ? Le cas du m\u00e9tavers (with J. Da Silva)\", \"year\": 2026, \"venue\": \"Le podcast natif (\u00c9ditions Panth\u00e9on-Assas), pp. 299-312\", \"url\": \"https://carism.assas-universite.fr/fr/universite/contacts/enseignants-chercheurs/m-jaercio-da-silva\", \"link_to_user\": \"\u5143\u5b87\u5b99/\u6c89\u6d78\u6280\u672f\u7684\u516c\u5171\u8bdd\u8bed \u2192 \u53ef\u4f5c\u4e3a\u7528\u6237\u7814\u7a76\u201c\u6570\u5b57\u9057\u4ea7\u6c89\u6d78\u4f53\u9a8c\u5982\u4f55\u88ab\u516c\u4f17\u7406\u89e3\u201d\u7684\u793e\u4f1a\u5b66\u6846\u67b6\", \"title_zh\": \"\u6280\u672f\u80fd\u5426\u878d\u5165\u64ad\u5ba2\uff1f\u4ee5\u5143\u5b87\u5b99\u4e3a\u4f8b\uff08\u4e0e J. Da Silva \u5408\u8457\uff09\"}, {\"title\": \"La chose qu'on ne peut pas nommer. Exp\u00e9rimentations autour du m\u00e9tavers au Qu\u00e9bec (with J. Da Silva)\", \"year\": 2026, \"venue\": \"RESET 17/1 (\u00e0 para\u00eetre)\", \"url\": \"https://carism.assas-universite.fr/fr/universite/contacts/enseignants-chercheurs/m-jaercio-da-silva\", \"link_to_user\": \"\u9b41\u5317\u514b\u6c89\u6d78\u5f0f\u6587\u5316\u4ea7\u4e1a\u5b9e\u9a8c\u7684\u6c11\u65cf\u5fd7 \u2192 \u5bf9\u5e94\u7528\u6237\u5728\u535a\u7269\u9986\u90e8\u7f72\u539f\u578b\u7684\u7530\u91ce\u65b9\u6cd5\", \"title_zh\": \"\u65e0\u6cd5\u547d\u540d\u4e4b\u7269\uff1a\u9b41\u5317\u514b\u5143\u5b87\u5b99\u76f8\u5173\u5b9e\u9a8c\uff08\u4e0e J. Da Silva \u5408\u8457\uff09\"}, {\"title\": \"An Industry Without a Market? Funding Policies and the Immersive Innovation Economy (with J. Da Silva)\", \"year\": 2026, \"venue\": \"Journal of Digital Media & Policy 17/2 (\u00e0 para\u00eetre)\", \"url\": \"https://carism.assas-universite.fr/fr/universite/contacts/enseignants-chercheurs/m-jaercio-da-silva\", \"link_to_user\": \"\u6c89\u6d78\u5f0f\u521b\u65b0\u7ecf\u6d4e\u7684\u8d44\u52a9\u653f\u7b56 \u2192 \u4e0e\u975e\u9057\u6570\u5b57\u5316\u9879\u76ee\u7684\u4ea7\u4e1a/\u653f\u7b56\u8bed\u5883\u76f8\u5173\", \"title_zh\": \"\u6ca1\u6709\u5e02\u573a\u7684\u4ea7\u4e1a\uff1f\u8d44\u52a9\u653f\u7b56\u4e0e\u6c89\u6d78\u5f0f\u521b\u65b0\u7ecf\u6d4e\uff08\u4e0e J. Da Silva \u5408\u8457\uff09\"}], \"evidence_projects_funding\": \"CARISM \u4e3b\u4efb\uff1b\u4e0e Jo\u00eblle Farchy \u5171\u540c\u4e3b\u6301 Chaire PcEn\uff08Pluralisme culturel et \u00c9thique du num\u00e9rique\uff0cParis 1 + Paris 2\uff09\uff1bPEPR ICCARE \u7684 STYX \u9879\u76ee\u6210\u5458\uff1b2023 \u5e74\u7ec4\u7ec7 CARISM \u5143\u5b87\u5b99\u56fd\u9645\u7814\u8ba8\u4f1a\u3002\", \"fit_to_user\": \"\u53ea\u80fd\u4ee5\u201c\u6c89\u6d78\u5f0f\u6587\u5316\u4f53\u9a8c\u7684\u4f7f\u7528\u4e0e\u516c\u4f17\u201d\u5207\u5165\uff0c\u628a\u7528\u6237\u7684\u624b\u52bf\u7c92\u5b50\u4ea4\u4e92\u653e\u5230\u5a92\u4ecb\u793e\u4f1a\u5b66/\u7528\u6237\u7814\u7a76\u6846\u67b6\u4e0b\uff1b\u5bf9\u7528\u6237\u505a\u6280\u672f\u539f\u578b\u7684\u5f3a\u9879\u5229\u7528\u6709\u9650\u3002\", \"counterargument_risk\": \"\u5b66\u79d1\u662f SIC\uff08\u4fe1\u606f\u4f20\u64ad\u5b66\uff09/\u793e\u4f1a\u5b66\uff0c\u975e\u8bbe\u8ba1/HCI\uff1b\u8bba\u6587\u591a\u4e3a\u6cd5\u8bed\uff1bAssas \u65e0 CSC \u5408\u4f5c\u9879\u76ee\uff1b\u4f5c\u4e3a\u526f\u6821\u957f\u4e0e\u5b9e\u9a8c\u5ba4\u4e3b\u4efb\uff0c\u62db\u751f\u7cbe\u529b\u53ef\u80fd\u6709\u9650\uff1b\u65b9\u5411\u9519\u4f4d\u98ce\u9669\u9ad8\uff0c\u4ec5\u4f5c\u515c\u5e95\u3002\", \"email_hook\": \"Your recent work with Ja\u00e9rcio da Silva on how the metaverse is experimented with and talked about made me wonder how visitors make sense of gesture-driven heritage installations.\", \"sources\": [\"https://www.assas-universite.fr/fr/universite/contacts/enseignants-chercheurs/mme-cecile-meadel\", \"https://carism.assas-universite.fr/fr/equipe-carism\", \"https://www.csi.minesparis.psl.eu/en/people/associated-researchers/cecile-meadel\", \"https://pepr-iccare.fr/team-member/cecile-meadel\"], \"verified\": true, \"csc_note\": \"\u672a\u627e\u5230 Paris-Panth\u00e9on-Assas \u7684 CSC \u535a\u58eb\u5408\u4f5c\u9879\u76ee\u9875\u9762\uff08data/csc.json status=not_found\uff09\uff1b\u53ea\u80fd\u8d70 CSC \u56fd\u5bb6\u516c\u6d3e\u81ea\u4e3b\u8054\u7cfb\u6216\u6cd5\u56fd\u5176\u4ed6\u8d44\u52a9\uff08CIFRE/\u5b66\u6821\u5408\u540c\uff09\uff0c\u9700\u53e6\u884c\u786e\u8ba4\", \"matched_keywords\": [\"immersive technologies\", \"metaverse\", \"digital media\", \"media studies\"], \"csc_status\": \"not_found\", \"in_user_csc_list\": true, \"email_draft\": {\"to\": \"cecile.meadel@u-paris2.fr\", \"subject\": \"PhD enquiry: how visitors make sense of gesture-driven immersive heritage\", \"body\": \"Dear Professor M\u00e9adel,\\n\\nYour recent work with Ja\u00e9rcio da Silva on the metaverse, from the Qu\u00e9bec experiments to the funding of the immersive innovation economy, is the closest media-studies lens I have found for the installations I build. I would like to apply for a PhD at CARISM (Universit\u00e9 Paris-Panth\u00e9on-Assas) under your direction, starting in 2027.\\n\\nSince November 2025 I have directed the Digital ICH Design and Production Teaching and Research Office at Quanzhou Huaguang College, teaching 3D character design, digital sculpting and cultural-product design, supervising student 3D content production and leading a VR collaborative lighting design project (JAT251371). Previously, as a lighting hardware product manager, I ran nine product families at OSRAM/LEDVANCE (~100 SKUs, ~US$8M in sales), including light-distribution analysis for Abu Dhabi's Zayed Airport, and led user research (Amazon data, DEMATEL) at LEEDARSON for smart-lighting lines selling over US$30M. My LEEDARSON research included studying online (Discord) user communities.\\n\\nMy most relevant prototype is Stone Reveal (https://cooleli.github.io/Portfolio-page/Dunhuang%20Interactive%20Heritage%20project/): four Dunhuang Buddha figures as Three.js particle clouds; with in-browser MediaPipe hand tracking, visitors brush away the \\\"dust\\\" and join palms to reveal the gilded figure. A companion project does this for Chinese bronzes.\\n\\nFor a PhD I would like to study how visitors interpret, talk about and value gesture-driven immersive heritage installations: combining the prototype as a probe with interviews and online ethnography of how such experiences circulate, so that the design questions (gesture, light, narrative) are grounded in a sociology of use.\\n\\nTo be direct: my degrees are in design (M.F.A. in Digital Art Design, B.A. in Product Design), not computer science, and I have no first-author paper yet (two co-authored MR papers). I bring working prototypes, a granted MR invention patent and a practice-based approach I would turn into peer-reviewed studies early.\\n\\nI realise my profile is closer to design than to information and communication sciences, and I would welcome your view on whether this topic could fit CARISM, possibly co-supervised with Dr da Silva. I would be glad to send a two-page proposal.\\n\\nBest regards,\\nHanlei (Eli) Zeng\\nDirector, Digital ICH Design & Production Teaching and Research Office, Quanzhou Huaguang College, China\\nPortfolio & CV: https://cooleli.github.io/CV-project/v2/\", \"note_zh\": \"\u5207\u5165\u70b9\uff1a\u5979\u4e0e da Silva \u7684\u5143\u5b87\u5b99/\u6c89\u6d78\u4ea7\u4e1a\u7814\u7a76\u3002\u53d1\u9001\u524d\u786e\u8ba4\uff1a\u2460\u6cd5\u8bed\u80fd\u529b\uff08CARISM \u8bba\u6587\u4e0e\u8bfe\u7a0b\u591a\u4e3a\u6cd5\u8bed\uff0c\u53ef\u80fd\u8981\u6c42 B2/C1\uff09\uff1b\u2461Assas \u65e0 CSC \u5408\u4f5c\u9879\u76ee\uff0c\u9700\u8d70\u56fd\u5bb6\u516c\u6d3e\u81ea\u4e3b\u8054\u7cfb\u6216\u5176\u4ed6\u8d44\u52a9\uff1b\u2462\u65b9\u5411\u662f\u4f20\u64ad\u793e\u4f1a\u5b66\u800c\u975e\u8bbe\u8ba1\uff0c\u76f8\u5173\u5ea6\u4f4e\uff0c\u5efa\u8bae\u4ec5\u5728\u5176\u4ed6\u6cd5\u56fd\u5b66\u6821\u65e0\u56de\u97f3\u65f6\u53d1\u9001\uff1b\u2463\u53ef\u8003\u8651\u540c\u65f6\u6284\u9001/\u6539\u53d1 da Silva\u3002\", \"subject_zh\": \"\u535a\u58eb\u7533\u8bf7\u54a8\u8be2\uff1a\u89c2\u4f17\u5982\u4f55\u7406\u89e3\u624b\u52bf\u9a71\u52a8\u7684\u6c89\u6d78\u5f0f\u9057\u4ea7\", \"body_zh\": \"\u5c0a\u656c\u7684 M\u00e9adel \u6559\u6388\uff1a\\n\\n\u60a8\u8fd1\u671f\u4e0e Ja\u00e9rcio da Silva \u5408\u4f5c\u7684\u5143\u5b87\u5b99\u7814\u7a76\u2014\u2014\u4ece\u9b41\u5317\u514b\u7684\u5b9e\u9a8c\u5230\u6c89\u6d78\u5f0f\u521b\u65b0\u7ecf\u6d4e\u7684\u878d\u8d44\u2014\u2014\u662f\u6211\u6240\u627e\u5230\u7684\u3001\u89c2\u5bdf\u6211\u6240\u5236\u4f5c\u7684\u88c5\u7f6e\u6700\u8d34\u8fd1\u7684\u5a92\u4ecb\u7814\u7a76\u89c6\u89d2\u3002\u6211\u5e0c\u671b\u5728\u60a8\u7684\u6307\u5bfc\u4e0b\u7533\u8bf7\u5df4\u9ece-\u5148\u8d24\u7960-\u963f\u8428\u65af\u5927\u5b66 CARISM \u7814\u7a76\u4e2d\u5fc3\u7684\u535a\u58eb\uff0c2027 \u5e74\u5165\u5b66\u3002\\n\\n\u81ea 2025 \u5e74 11 \u6708\u8d77\uff0c\u6211\u62c5\u4efb\u6cc9\u5dde\u534e\u5149\u804c\u4e1a\u5b66\u9662\u6570\u5b57\u975e\u9057\u8bbe\u8ba1\u4e0e\u5236\u4f5c\u6559\u7814\u5ba4\u4e3b\u4efb\uff0c\u4e3b\u8bb2 3D \u89d2\u8272\u8bbe\u8ba1\u3001\u6570\u5b57\u96d5\u523b\u4e0e\u6587\u521b\u4ea7\u54c1\u8bbe\u8ba1\uff0c\u6307\u5bfc\u5b66\u751f\u7684 3D \u5185\u5bb9\u751f\u4ea7\uff0c\u5e76\u4e3b\u6301\u4e00\u9879 VR \u534f\u540c\u7167\u660e\u8bbe\u8ba1\u7814\u7a76\u9879\u76ee\uff08JAT251371\uff09\u3002\u6b64\u524d\u6211\u662f\u7167\u660e\u786c\u4ef6\u4ea7\u54c1\u7ecf\u7406\uff1a\u5728 OSRAM/LEDVANCE\uff08\u6b27\u53f8\u6717/\u6717\u5fb7\u4e07\u65af\uff09\u8d1f\u8d23 9 \u4e2a\u4ea7\u54c1\u7cfb\u5217\uff08\u7ea6 100 \u4e2a SKU\uff0c\u7d2f\u8ba1\u9500\u552e\u7ea6 800 \u4e07\u7f8e\u5143\uff09\uff0c\u5176\u4e2d\u5305\u62ec\u4e3a\u963f\u5e03\u624e\u6bd4 Zayed \u673a\u573a\u9879\u76ee\u505a\u914d\u5149\u5206\u6790\uff1b\u5728 LEEDARSON\uff08\u7acb\u8fbe\u4fe1\uff09\u4e3b\u5bfc\u667a\u80fd\u7167\u660e\u4ea7\u54c1\u7ebf\u7684\u7528\u6237\u7814\u7a76\uff08\u4e9a\u9a6c\u900a\u6570\u636e\u3001DEMATEL\uff09\uff0c\u8fd9\u4e9b\u4ea7\u54c1\u7ebf\u7d2f\u8ba1\u9500\u552e\u8d85\u8fc7 3000 \u4e07\u7f8e\u5143\u3002\u6211\u5728\u7acb\u8fbe\u4fe1\u7684\u7814\u7a76\u5de5\u4f5c\u5c31\u5305\u62ec\u7814\u7a76\u7ebf\u4e0a\uff08Discord\uff09\u7528\u6237\u793e\u7fa4\u3002\\n\\n\u4e0e\u6b64\u6700\u76f8\u5173\u7684\u539f\u578b\u662f Stone Reveal\uff08\u300a\u77f3\u50cf\u663e\u73b0\u300b\uff09\uff08https://cooleli.github.io/Portfolio-page/Dunhuang%20Interactive%20Heritage%20project/\uff09\uff1a\u56db\u5c0a\u6566\u714c\u4f5b\u50cf\u88ab\u505a\u6210 Three.js \u7c92\u5b50\u4e91\uff1b\u501f\u52a9\u6d4f\u89c8\u5668\u5185\u7684 MediaPipe \u624b\u90e8\u8ffd\u8e2a\uff0c\u89c2\u4f17\u62c2\u53bb\u201c\u5c18\u571f\u201d\uff0c\u53cc\u624b\u5408\u5341\u5373\u53ef\u663e\u73b0\u938f\u91d1\u4f5b\u8eab\u3002\u53e6\u4e00\u4e2a\u914d\u5957\u9879\u76ee\u4ee5\u540c\u6837\u65b9\u5f0f\u5448\u73b0\u4e2d\u56fd\u9752\u94dc\u5668\u3002\\n\\n\u5728\u535a\u58eb\u9636\u6bb5\uff0c\u6211\u5e0c\u671b\u7814\u7a76\u89c2\u4f17\u5982\u4f55\u89e3\u8bfb\u3001\u8c08\u8bba\u548c\u8bc4\u4ef7\u624b\u52bf\u9a71\u52a8\u7684\u6c89\u6d78\u5f0f\u9057\u4ea7\u88c5\u7f6e\uff1a\u628a\u539f\u578b\u4f5c\u4e3a\u63a2\u9488\uff0c\u7ed3\u5408\u8bbf\u8c08\u4ee5\u53ca\u5bf9\u8fd9\u7c7b\u4f53\u9a8c\u5982\u4f55\u4f20\u64ad\u7684\u7f51\u7edc\u6c11\u65cf\u5fd7\uff0c\u4f7f\u8bbe\u8ba1\u95ee\u9898\uff08\u624b\u52bf\u3001\u5149\u3001\u53d9\u4e8b\uff09\u5efa\u7acb\u5728\u4f7f\u7528\u793e\u4f1a\u5b66\u7684\u57fa\u7840\u4e4b\u4e0a\u3002\\n\\n\u5766\u767d\u5730\u8bf4\uff1a\u6211\u7684\u5b66\u4f4d\u662f\u8bbe\u8ba1\u5b66\uff08\u6570\u5b57\u827a\u672f\u8bbe\u8ba1 M.F.A.\u3001\u4ea7\u54c1\u8bbe\u8ba1 B.A.\uff09\u800c\u975e\u8ba1\u7b97\u673a\u79d1\u5b66\uff0c\u76ee\u524d\u8fd8\u6ca1\u6709\u7b2c\u4e00\u4f5c\u8005\u8bba\u6587\uff08\u6709\u4e24\u7bc7\u5408\u8457\u7684 MR \u8bba\u6587\uff09\u3002\u6211\u80fd\u5e26\u6765\u7684\u662f\u53ef\u8fd0\u884c\u7684\u539f\u578b\u3001\u4e00\u9879 MR \u9886\u57df\u7684\u5df2\u6388\u6743\u53d1\u660e\u4e13\u5229\uff0c\u4ee5\u53ca\u4e00\u5957\u5b9e\u8df5\u578b\u7814\u7a76\u65b9\u6cd5\uff0c\u6211\u4f1a\u5728\u65e9\u671f\u5c31\u628a\u5b83\u8f6c\u5316\u4e3a\u7ecf\u540c\u884c\u8bc4\u5ba1\u7684\u7814\u7a76\u3002\\n\\n\u6211\u610f\u8bc6\u5230\u6211\u7684\u80cc\u666f\u66f4\u63a5\u8fd1\u8bbe\u8ba1\u800c\u975e\u4fe1\u606f\u4e0e\u4f20\u64ad\u79d1\u5b66\uff0c\u975e\u5e38\u5e0c\u671b\u542c\u5230\u60a8\u7684\u770b\u6cd5\uff1a\u8fd9\u4e00\u8bfe\u9898\u80fd\u5426\u5951\u5408 CARISM\uff0c\u6216\u8bb8\u53ef\u7531 da Silva \u535a\u58eb\u8054\u5408\u6307\u5bfc\u3002\u6211\u5f88\u4e50\u610f\u5bc4\u4e0a\u4e00\u4efd\u4e24\u9875\u7684\u7814\u7a76\u8ba1\u5212\u3002\\n\\n\u6b64\u81f4\\n\u656c\u793c\\nHanlei (Eli) Zeng\uff08\u66fe\u97e9\u64c2\uff09\\n\u4e2d\u56fd\u6cc9\u5dde\u534e\u5149\u804c\u4e1a\u5b66\u9662 \u6570\u5b57\u975e\u9057\u8bbe\u8ba1\u4e0e\u5236\u4f5c\u6559\u7814\u5ba4\u4e3b\u4efb\\n\u4f5c\u54c1\u96c6\u4e0e\u7b80\u5386\uff1ahttps://cooleli.github.io/CV-project/v2/\"}, \"phd_students\": {\"found\": true, \"students\": [{\"name\": \"Marguerite Borelli\", \"status\": \"alumni\", \"thesis_title\": \"Les g\u00e9ants du num\u00e9rique face au terrorisme : privatisation et gouvernance d'un enjeu de s\u00e9curit\u00e9 nationale \u00e0 l'\u00e9chelle globale\", \"topic_zh\": \"\u6570\u5b57\u5de8\u5934\u4e0e\u53cd\u6050\uff1a\u5b89\u5168\u8bae\u9898\u7684\u79c1\u6709\u5316\u4e0e\u6cbb\u7406\", \"url\": \"https://theses.fr/2025ASSA0024\", \"graduation_year\": 2025}, {\"name\": \"Ja\u00e9rcio Da Silva\", \"status\": \"alumni\", \"thesis_title\": \"Un concept sur la toile. Circulation et traduction \u00e0 bas bruit de l'intersectionnalit\u00e9\", \"topic_zh\": \"\u201c\u4ea4\u53c9\u6027\u201d\u6982\u5ff5\u5728\u7f51\u7edc\u4e0a\u7684\u6d41\u901a\u4e0e\u8f6c\u8bd1\", \"url\": \"https://theses.fr/2022ASSA0036\", \"graduation_year\": 2022, \"now\": \"Paris-Panth\u00e9on-Assas IFP/CARISM \u6559\u5e08\", \"now_zh\": \"Paris-Panth\u00e9on-Assas IFP/CARISM \u6559\u5e08\"}, {\"name\": \"Victoria Laurent\", \"status\": \"alumni\", \"thesis_title\": \"\u00ab Les citoyens auteurs de la loi \u00bb : la consultation en ligne R\u00e9publique num\u00e9rique ...\", \"topic_zh\": \"\u5728\u7ebf\u7acb\u6cd5\u54a8\u8be2\u4e2d\u7684\u4e2d\u4ecb\u8fc7\u7a0b\", \"url\": \"https://theses.fr/2021PA020076\", \"graduation_year\": 2021}, {\"name\": \"Fr\u00e9d\u00e9rick Bigrat\", \"status\": \"alumni\", \"thesis_title\": \"Conception de MOOC en France entre 2012 et 2020 ...\", \"topic_zh\": \"\u6cd5\u56fd MOOC \u8bbe\u8ba1\u5bf9\u6559\u5e08\u6559\u5b66\u5b9e\u8df5\u7684\u5f71\u54cd\", \"url\": \"https://theses.fr/2021PA020021\", \"graduation_year\": 2021}, {\"name\": \"Blandine Rousselin\", \"status\": \"alumni\", \"thesis_title\": \"''Rester en vie dans un monde fou'', la mise en r\u00e9cit des troubles sur le web\", \"topic_zh\": \"\u7f51\u7edc\u4e0a\u7684\u5fc3\u7406\u56f0\u6270\u53d9\u4e8b\", \"url\": \"https://theses.fr/2020PA020039\", \"graduation_year\": 2020}, {\"name\": \"Nina Fernandes dos Santos\", \"status\": \"alumni\", \"thesis_title\": \"The reconfiguration of the communication environment: twitter in the 2013 Brazilian protests\", \"topic_zh\": \"2013 \u5df4\u897f\u6297\u8bae\u4e2d\u7684 Twitter \u4e0e\u4f20\u64ad\u73af\u5883\u91cd\u6784\", \"url\": \"https://theses.fr/2019PA020086\", \"graduation_year\": 2019}, {\"name\": \"Oph\u00e9lie Coelho\", \"status\": \"current\", \"research_topic\": \"Points de connexion, lignes de fracture : La num\u00e9risation comme vecteur de mutation des pouvoirs ... en Afrique australe\", \"topic_zh\": \"\u5357\u90e8\u975e\u6d32\u6570\u5b57\u5316\u4e0e\u6743\u529b\u53d8\u8fc1\", \"url\": \"https://theses.fr/s416134\", \"start_year\": 2023}, {\"name\": \"Phoebe Pigenet\", \"status\": \"current\", \"research_topic\": \"Production, circulation et critique des normes de beaut\u00e9 par les marges sur les r\u00e9seaux sociaux num\u00e9riques\", \"topic_zh\": \"\u793e\u4ea4\u5a92\u4f53\u8fb9\u7f18\u7fa4\u4f53\u7684\u7f8e\u4e3d\u89c4\u8303\", \"url\": \"https://theses.fr/s416521\", \"start_year\": 2022}, {\"name\": \"Guillaume Jarousseau\", \"status\": \"current\", \"research_topic\": \"Sortir de l'illectronisme : Assignation, disqualification et formation au num\u00e9rique\", \"topic_zh\": \"\u6570\u5b57\u6587\u76f2\u4e0e\u6570\u5b57\u6280\u80fd\u57f9\u8bad\", \"url\": \"https://theses.fr/s416332\", \"start_year\": 2022}, {\"name\": \"Guillaume Vincent\", \"status\": \"current\", \"research_topic\": \"Le d\u00e9bat public dans les conversations en ligne : le cas du v\u00e9hicule \u00e9lectrique\", \"topic_zh\": \"\u5728\u7ebf\u5bf9\u8bdd\u4e2d\u7684\u516c\u5171\u8fa9\u8bba\uff1a\u7535\u52a8\u8f66\u6848\u4f8b\", \"url\": \"https://theses.fr/s416653\", \"start_year\": 2022}], \"total_estimate\": \"\u5728\u8bfb\u7ea6 5 / \u8fd1 10 \u5e74\u6bd5\u4e1a\u7ea6 8\uff08theses.fr\uff09\", \"student_pattern_zh\": \"\u4fe1\u606f\u4f20\u64ad\u5b66/\u79d1\u6280\u793e\u4f1a\u5b66\uff08STS\uff09\uff1a\u5e73\u53f0\u6cbb\u7406\u3001\u7f51\u7edc\u516c\u5171\u8fa9\u8bba\u3001\u6570\u5b57\u4e0d\u5e73\u7b49\u3001\u7f51\u7edc\u53d9\u4e8b\uff1b\u8d28\u6027\u793e\u4f1a\u5b66\u65b9\u6cd5\uff08\u7530\u91ce\u3001\u8bbf\u8c08\u3001\u8bdd\u8bed\u5206\u6790\uff09\uff0c\u7406\u8bba\u578b\u3002\", \"design_background_ok_zh\": \"\u5b66\u751f\u5747\u4e3a\u793e\u79d1/\u4f20\u64ad\u5b66\u80cc\u666f\uff0c\u975e CS\uff1b\u4f46\u672a\u89c1\u8bbe\u8ba1\u5b9e\u8df5\u7c7b\u535a\u58eb\u3002\", \"chinese_students_zh\": \"\u672a\u89c1\u4e2d\u56fd\u5b66\u751f\u8bb0\u5f55\u3002\", \"implication_zh\": \"\u4e0e\u7528\u6237\u7684\u8bbe\u8ba1+\u6280\u672f\u5b9e\u8df5\u65b9\u5411\u5dee\u8ddd\u5927\uff1b\u4ec5\u5728\u7528\u6237\u8f6c\u5411\u201c\u6570\u5b57\u9057\u4ea7\u7684\u793e\u4f1a\u4e0e\u4f20\u64ad\u7814\u7a76\uff08\u5982\u865a\u62df\u4e16\u754c\u3001\u5e73\u53f0\uff09\u201d\u65f6\u53ef\u8003\u8651\u3002\u6cd5\u56fd SIC \u535a\u58eb\u9700\u6cd5\u8bed\u80fd\u529b\uff0c\u98ce\u9669\u9ad8\u3002\", \"sources\": [\"https://theses.fr/2022ASSA0036\", \"https://theses.fr/2025ASSA0024\", \"https://carism.assas-universite.fr/fr/equipe-carism\"], \"searched\": [\"theses.fr API\uff08directeurs=M\u00e9adel\uff09\", \"CARISM \u56e2\u961f\u9875\"]}, \"title_zh\": \"Professeure des universit\u00e9s\uff08\u4fe1\u606f\u4e0e\u4f20\u64ad\u79d1\u5b66\u6b63\u6559\u6388\uff09\uff1bCARISM \u4e3b\u4efb\uff1b\u6570\u5b57\u5316\u526f\u6821\u957f\", \"unit_zh\": \"\u6cd5\u56fd\u65b0\u95fb\u5b66\u9662\uff08IFP\uff09/ CARISM\uff08EA 2293\uff09\uff0c\u5df4\u9ece-\u5148\u8d24\u7960-\u963f\u8428\u65af\u5927\u5b66\", \"evidence_projects_funding_zh\": \"CARISM \u4e3b\u4efb\uff1b\u4e0e Jo\u00eblle Farchy \u5171\u540c\u4e3b\u6301 Chaire PcEn\uff08\u6587\u5316\u591a\u5143\u4e0e\u6570\u5b57\u4f26\u7406\u8bb2\u5e2d\uff0cPluralisme culturel et \u00c9thique du num\u00e9rique\uff0c\u5df4\u9ece\u7b2c\u4e00\u5927\u5b66 + \u5df4\u9ece\u7b2c\u4e8c\u5927\u5b66\uff09\uff1bPEPR ICCARE \u7684 STYX \u9879\u76ee\u6210\u5458\uff1b2023 \u5e74\u7ec4\u7ec7 CARISM \u5143\u5b87\u5b99\u56fd\u9645\u7814\u8ba8\u4f1a\u3002\", \"email_hook_zh\": \"\u60a8\u8fd1\u671f\u4e0e Ja\u00e9rcio da Silva \u5408\u4f5c\u7684\u5173\u4e8e\u4eba\u4eec\u5982\u4f55\u8bd5\u9a8c\u548c\u8c08\u8bba\u5143\u5b87\u5b99\u7684\u7814\u7a76\uff0c\u8ba9\u6211\u601d\u8003\u89c2\u4f17\u5982\u4f55\u7406\u89e3\u624b\u52bf\u9a71\u52a8\u7684\u9057\u4ea7\u88c5\u7f6e\u3002\", \"csc_status_zh\": \"\u672a\u627e\u5230\"}, {\"name\": \"Dr. Ja\u00e9rcio da Silva\", \"school_en\": \"Universit\u00e9 Paris-Panth\u00e9on-Assas (Paris II)\", \"school_zh\": \"\u5df4\u9ece\u7b2c\u4e8c\u5927\u5b66\", \"country\": \"\", \"title\": \"Ma\u00eetre de conf\u00e9rences (Sciences de l'information et de la communication); Directeur de la Licence Information-Communication\", \"unit\": \"Institut fran\u00e7ais de presse (IFP) / CARISM, Universit\u00e9 Paris-Panth\u00e9on-Assas\", \"homepage\": \"https://carism.assas-universite.fr/fr/universite/contacts/enseignants-chercheurs/m-jaercio-da-silva\", \"email\": \"jaercio.dasilva@assas-universite.fr\", \"relevance\": 3, \"claim\": \"da Silva \u662f Assas \u552f\u4e00\u628a\u201c\u6c89\u6d78\u5f0f\u3001\u865a\u62df\u4e0e\u751f\u6210\u5f0f\u6280\u672f\u201d\u5217\u4e3a\u5f53\u524d\u4e3b\u7814\u65b9\u5411\u7684\u6559\u5e08\uff0c\u9002\u5408\u4f5c\u4e3a\u5171\u540c\u5bfc\u5e08\uff1b\u4f46\u4ed6\u662f MCF\uff08\u672a\u89c1 HDR\uff09\uff0c\u4e0d\u80fd\u5355\u72ec\u505a\u535a\u5bfc\u3002\", \"evidence_homepage\": \"https://carism.assas-universite.fr/fr/universite/contacts/enseignants-chercheurs/m-jaercio-da-silva\", \"evidence_papers\": [{\"title\": \"Mapping the Metaverse: Discourse, Media and Cultural Production\", \"year\": 2026, \"venue\": \"Studies in Communication Sciences (SComS), \u00e0 para\u00eetre\", \"url\": \"https://carism.assas-universite.fr/fr/universite/contacts/enseignants-chercheurs/m-jaercio-da-silva\", \"link_to_user\": \"\u5143\u5b87\u5b99\u4f5c\u4e3a\u6587\u5316\u751f\u4ea7\u7684\u8bdd\u8bed\u5206\u6790 \u2192 \u4e3a\u7528\u6237\u7684\u865a\u62df\u535a\u7269\u9986/XR \u6587\u5316\u9057\u4ea7\u63d0\u4f9b\u6587\u5316\u4ea7\u4e1a\u8bed\u5883\", \"title_zh\": \"\u7ed8\u5236\u5143\u5b87\u5b99\uff1a\u8bdd\u8bed\u3001\u5a92\u4ecb\u4e0e\u6587\u5316\u751f\u4ea7\"}, {\"title\": \"Transparence et explicabilit\u00e9 de l'IA : enjeux et demandes sociales dans le cas des industries culturelles (with J. Farchy)\", \"year\": 2026, \"venue\": \"Les Enjeux de l'information et de la communication\", \"url\": \"https://lesenjeux.univ-grenoble-alpes.fr/2026/varia/transparence-et-explicabilite-de-lia-enjeux-et-demandes-sociales-dans-le-cas-des-industries-culturelles/\", \"link_to_user\": \"\u6587\u5316\u4ea7\u4e1a\u4e2d\u7684\u65b0\u6280\u672f\u4e0e\u793e\u4f1a\u9700\u6c42 \u2192 \u4e0e\u975e\u9057\u6570\u5b57\u5316\u7684\u4f26\u7406/\u63a5\u53d7\u5ea6\u95ee\u9898\u76f8\u5173\", \"title_zh\": \"\u4eba\u5de5\u667a\u80fd\u7684\u900f\u660e\u6027\u4e0e\u53ef\u89e3\u91ca\u6027\uff1a\u4ee5\u6587\u5316\u4ea7\u4e1a\u4e3a\u4f8b\u7684\u5229\u5bb3\u4e0e\u793e\u4f1a\u9700\u6c42\uff08\u4e0e J. Farchy \u5408\u4f5c\uff09\"}, {\"title\": \"US-based SVOD services and the restructuring of the audio-visual production market: The French case (with G. Stephan, J. Farchy)\", \"year\": 2023, \"venue\": \"Journal of Digital Media & Policy 14/3, pp. 323-338\", \"url\": \"https://hal.science/hal-04412145v1\", \"link_to_user\": \"\u4ec5\u8bf4\u660e\u5176\u6570\u5b57\u5a92\u4f53\u4ea7\u4e1a\u7814\u7a76\u80cc\u666f\uff0c\u4e0e\u7528\u6237\u9879\u76ee\u95f4\u63a5\u76f8\u5173\", \"title_zh\": \"\u7f8e\u56fdSVOD\u6d41\u5a92\u4f53\u670d\u52a1\u4e0e\u89c6\u542c\u5236\u4f5c\u5e02\u573a\u7684\u91cd\u6784\uff1a\u6cd5\u56fd\u6848\u4f8b\uff08\u4e0e G. Stephan\u3001J. Farchy \u5408\u4f5c\uff09\"}], \"evidence_projects_funding\": \"CARISM \u6210\u5458\uff1bMaster 1 UNIC\uff08Usages du num\u00e9rique, Innovation et Communication\uff09\u8d1f\u8d23\u4eba\u3001Master CVTN \u5171\u540c\u8d1f\u8d23\u4eba\uff1bChaire PcEn \u5408\u4f5c\u7814\u7a76\u5143\u5b87\u5b99\uff08\u591a\u7bc7 PcEn \u79d1\u666e\u7a3f\uff09\uff1bRESET \u7f16\u59d4\uff082025 \u8d77\uff09\u3002\", \"fit_to_user\": \"\u7814\u7a76\u5bf9\u8c61\uff08\u6c89\u6d78\u5f0f\u6280\u672f\u7684\u4f7f\u7528\u4e0e\u5e02\u573a\uff09\u4e0e\u7528\u6237\u7684 XR \u6587\u5316\u9057\u4ea7\u4f5c\u54c1\u6709\u4ea4\u96c6\uff0c\u53ef\u4ece\u201c\u7528\u6237/\u89c2\u4f17\u7814\u7a76\u3001\u5728\u7ebf\u6c11\u65cf\u5fd7\u201d\u89d2\u5ea6\u8865\u8db3\u7528\u6237\u8bba\u6587\u7684\u793e\u4f1a\u7ef4\u5ea6\u3002\", \"counterargument_risk\": \"MCF \u8eab\u4efd\uff0c\u4e3b\u5bfc\u5e08\u987b\u7531 HDR \u6559\u6388\uff08\u5982 M\u00e9adel\uff09\u62c5\u4efb\uff1b\u65b9\u6cd5\u662f\u8d28\u6027\u793e\u4f1a\u5b66\uff0c\u4e0d\u505a\u539f\u578b\u6216\u5b9e\u9a8c\uff1b\u6cd5\u8bed\u4e3a\u4e3b\u8981\u5de5\u4f5c\u8bed\u8a00\uff1b\u65e0 CSC \u9879\u76ee\uff1b\u76f8\u5173\u5ea6\u4f4e\u3002\", \"email_hook\": \"Your current work on immersive and generative technologies as emerging fields in the cultural industries is directly relevant to how heritage XR prototypes like mine are adopted.\", \"sources\": [\"https://carism.assas-universite.fr/fr/universite/contacts/enseignants-chercheurs/m-jaercio-da-silva\", \"https://carism.assas-universite.fr/sites/default/files/document/cvpublications/2026-cv-jaerciodasilva.pdf\", \"https://hal.science/hal-04412145v1\", \"https://cems.ehess.fr/system/files/2025-01/programme_je_sociologie_du_virtuel.pdf\"], \"verified\": true, \"csc_note\": \"\u672a\u627e\u5230 Paris-Panth\u00e9on-Assas \u7684 CSC \u535a\u58eb\u5408\u4f5c\u9879\u76ee\u9875\u9762\uff08data/csc.json status=not_found\uff09\uff1b\u53ea\u80fd\u8d70 CSC \u56fd\u5bb6\u516c\u6d3e\u81ea\u4e3b\u8054\u7cfb\u6216\u6cd5\u56fd\u5176\u4ed6\u8d44\u52a9\uff08CIFRE/\u5b66\u6821\u5408\u540c\uff09\uff0c\u9700\u53e6\u884c\u786e\u8ba4\", \"matched_keywords\": [\"immersive technologies\", \"virtual worlds\", \"digital media\", \"media studies\"], \"csc_status\": \"not_found\", \"in_user_csc_list\": true, \"email_draft\": {\"to\": \"jaercio.dasilva@assas-universite.fr\", \"subject\": \"PhD enquiry: immersive heritage installations and their publics (possible co-supervision)\", \"body\": \"Dear Dr da Silva,\\n\\nYour current research on immersive and generative technologies as emerging fields in the cultural industries, and your paper \\\"Mapping the Metaverse: Discourse, Media and Cultural Production\\\", speaks directly to the gap between heritage XR prototypes and the people who actually use them. I would like to apply for a PhD at CARISM (Universit\u00e9 Paris-Panth\u00e9on-Assas), ideally co-supervised by you, starting in 2027.\\n\\nSince November 2025 I have directed the Digital ICH Design and Production Teaching and Research Office at Quanzhou Huaguang College, teaching 3D character design, digital sculpting and cultural-product design, supervising student 3D content production and leading a VR collaborative lighting design project (JAT251371). Previously, as a lighting hardware product manager, I ran nine product families at OSRAM/LEDVANCE (~100 SKUs, ~US$8M in sales), including light-distribution analysis for Abu Dhabi's Zayed Airport, and led user research (Amazon data, DEMATEL) at LEEDARSON for smart-lighting lines selling over US$30M. My LEEDARSON work studied online user communities; my office teaches cultural-product design.\\n\\nMy most relevant prototype is Stone Reveal (https://cooleli.github.io/Portfolio-page/Dunhuang%20Interactive%20Heritage%20project/): four Dunhuang Buddha figures as Three.js particle clouds; with in-browser MediaPipe hand tracking, visitors brush away the \\\"dust\\\" and join palms to reveal the gilded figure. A companion project does this for Chinese bronzes.\\n\\nFor a PhD I would like to study how gesture-driven immersive heritage experiences are received and circulated: using my prototypes as probes in museums, combined with interviews and online ethnography of how visitors and institutions talk about such experiences.\\n\\nTo be direct: my degrees are in design (M.F.A. in Digital Art Design, B.A. in Product Design), not computer science, and I have no first-author paper yet (two co-authored MR papers). I bring working prototypes, a granted MR invention patent and a practice-based approach I would turn into peer-reviewed studies early.\\n\\nI understand that a thesis would need an HDR director, and I would be grateful for your advice on whether Professor M\u00e9adel or another CARISM colleague might direct it with you. I would be glad to send a two-page proposal.\\n\\nBest regards,\\nHanlei (Eli) Zeng\\nDirector, Digital ICH Design & Production Teaching and Research Office, Quanzhou Huaguang College, China\\nPortfolio & CV: https://cooleli.github.io/CV-project/v2/\", \"note_zh\": \"\u5207\u5165\u70b9\uff1a\u6c89\u6d78/\u751f\u6210\u6280\u672f\u5728\u6587\u5316\u4ea7\u4e1a\u4e2d\u7684\u7814\u7a76\u3002\u53d1\u9001\u524d\u786e\u8ba4\uff1a\u2460\u4ed6\u662f MCF\uff0c\u9700\u95ee\u6e05 HDR \u60c5\u51b5\u4e0e\u53ef\u5426\u5171\u540c\u6307\u5bfc\uff1b\u2461\u6cd5\u8bed\u8981\u6c42\uff1b\u2462Assas \u65e0 CSC \u5408\u4f5c\u9879\u76ee\uff1b\u2463\u76f8\u5173\u5ea6\u4f4e\uff0c\u5efa\u8bae\u4e0e M\u00e9adel \u4e8c\u9009\u4e00\u6216\u6253\u5305\u540c\u4e00\u5c01\u90ae\u4ef6\u6284\u9001\u4e24\u4eba\u3002\", \"subject_zh\": \"\u535a\u58eb\u7533\u8bf7\u54a8\u8be2\uff1a\u6c89\u6d78\u5f0f\u9057\u4ea7\u88c5\u7f6e\u53ca\u5176\u516c\u4f17\uff08\u53ef\u80fd\u7684\u8054\u5408\u6307\u5bfc\uff09\", \"body_zh\": \"\u5c0a\u656c\u7684 da Silva \u535a\u58eb\uff1a\\n\\n\u60a8\u76ee\u524d\u5173\u4e8e\u6c89\u6d78\u5f0f\u4e0e\u751f\u6210\u5f0f\u6280\u672f\u4f5c\u4e3a\u6587\u5316\u4ea7\u4e1a\u65b0\u5174\u9886\u57df\u7684\u7814\u7a76\uff0c\u4ee5\u53ca\u60a8\u7684\u8bba\u6587 \\\"Mapping the Metaverse: Discourse, Media and Cultural Production\\\"\uff08\u300a\u7ed8\u5236\u5143\u5b87\u5b99\uff1a\u8bdd\u8bed\u3001\u5a92\u4ecb\u4e0e\u6587\u5316\u751f\u4ea7\u300b\uff09\uff0c\u76f4\u63a5\u89e6\u53ca\u4e86\u9057\u4ea7 XR \u539f\u578b\u4e0e\u771f\u6b63\u4f7f\u7528\u5b83\u4eec\u7684\u4eba\u4e4b\u95f4\u7684\u9e3f\u6c9f\u3002\u6211\u5e0c\u671b\u7533\u8bf7\u5df4\u9ece-\u5148\u8d24\u7960-\u963f\u8428\u65af\u5927\u5b66 CARISM \u7814\u7a76\u4e2d\u5fc3\u7684\u535a\u58eb\uff0c\u6700\u597d\u7531\u60a8\u8054\u5408\u6307\u5bfc\uff0c2027 \u5e74\u5165\u5b66\u3002\\n\\n\u81ea 2025 \u5e74 11 \u6708\u8d77\uff0c\u6211\u62c5\u4efb\u6cc9\u5dde\u534e\u5149\u804c\u4e1a\u5b66\u9662\u6570\u5b57\u975e\u9057\u8bbe\u8ba1\u4e0e\u5236\u4f5c\u6559\u7814\u5ba4\u4e3b\u4efb\uff0c\u4e3b\u8bb2 3D \u89d2\u8272\u8bbe\u8ba1\u3001\u6570\u5b57\u96d5\u523b\u4e0e\u6587\u521b\u4ea7\u54c1\u8bbe\u8ba1\uff0c\u6307\u5bfc\u5b66\u751f\u7684 3D \u5185\u5bb9\u751f\u4ea7\uff0c\u5e76\u4e3b\u6301\u4e00\u9879 VR \u534f\u540c\u7167\u660e\u8bbe\u8ba1\u7814\u7a76\u9879\u76ee\uff08JAT251371\uff09\u3002\u6b64\u524d\u6211\u662f\u7167\u660e\u786c\u4ef6\u4ea7\u54c1\u7ecf\u7406\uff1a\u5728 OSRAM/LEDVANCE\uff08\u6b27\u53f8\u6717/\u6717\u5fb7\u4e07\u65af\uff09\u8d1f\u8d23 9 \u4e2a\u4ea7\u54c1\u7cfb\u5217\uff08\u7ea6 100 \u4e2a SKU\uff0c\u7d2f\u8ba1\u9500\u552e\u7ea6 800 \u4e07\u7f8e\u5143\uff09\uff0c\u5176\u4e2d\u5305\u62ec\u4e3a\u963f\u5e03\u624e\u6bd4 Zayed \u673a\u573a\u9879\u76ee\u505a\u914d\u5149\u5206\u6790\uff1b\u5728 LEEDARSON\uff08\u7acb\u8fbe\u4fe1\uff09\u4e3b\u5bfc\u667a\u80fd\u7167\u660e\u4ea7\u54c1\u7ebf\u7684\u7528\u6237\u7814\u7a76\uff08\u4e9a\u9a6c\u900a\u6570\u636e\u3001DEMATEL\uff09\uff0c\u8fd9\u4e9b\u4ea7\u54c1\u7ebf\u7d2f\u8ba1\u9500\u552e\u8d85\u8fc7 3000 \u4e07\u7f8e\u5143\u3002\u6211\u5728\u7acb\u8fbe\u4fe1\u7684\u5de5\u4f5c\u7814\u7a76\u8fc7\u7ebf\u4e0a\u7528\u6237\u793e\u7fa4\uff1b\u6211\u7684\u6559\u7814\u5ba4\u4e5f\u6559\u6388\u6587\u521b\u4ea7\u54c1\u8bbe\u8ba1\u3002\\n\\n\u4e0e\u6b64\u6700\u76f8\u5173\u7684\u539f\u578b\u662f Stone Reveal\uff08\u300a\u77f3\u50cf\u663e\u73b0\u300b\uff09\uff08https://cooleli.github.io/Portfolio-page/Dunhuang%20Interactive%20Heritage%20project/\uff09\uff1a\u56db\u5c0a\u6566\u714c\u4f5b\u50cf\u88ab\u505a\u6210 Three.js \u7c92\u5b50\u4e91\uff1b\u501f\u52a9\u6d4f\u89c8\u5668\u5185\u7684 MediaPipe \u624b\u90e8\u8ffd\u8e2a\uff0c\u89c2\u4f17\u62c2\u53bb\u201c\u5c18\u571f\u201d\uff0c\u53cc\u624b\u5408\u5341\u5373\u53ef\u663e\u73b0\u938f\u91d1\u4f5b\u8eab\u3002\u53e6\u4e00\u4e2a\u914d\u5957\u9879\u76ee\u4ee5\u540c\u6837\u65b9\u5f0f\u5448\u73b0\u4e2d\u56fd\u9752\u94dc\u5668\u3002\\n\\n\u5728\u535a\u58eb\u9636\u6bb5\uff0c\u6211\u5e0c\u671b\u7814\u7a76\u624b\u52bf\u9a71\u52a8\u7684\u6c89\u6d78\u5f0f\u9057\u4ea7\u4f53\u9a8c\u5982\u4f55\u88ab\u63a5\u53d7\u548c\u4f20\u64ad\uff1a\u628a\u6211\u7684\u539f\u578b\u4f5c\u4e3a\u535a\u7269\u9986\u4e2d\u7684\u63a2\u9488\uff0c\u7ed3\u5408\u8bbf\u8c08\u4ee5\u53ca\u5bf9\u89c2\u4f17\u548c\u673a\u6784\u5982\u4f55\u8c08\u8bba\u8fd9\u7c7b\u4f53\u9a8c\u7684\u7f51\u7edc\u6c11\u65cf\u5fd7\u3002\\n\\n\u5766\u767d\u5730\u8bf4\uff1a\u6211\u7684\u5b66\u4f4d\u662f\u8bbe\u8ba1\u5b66\uff08\u6570\u5b57\u827a\u672f\u8bbe\u8ba1 M.F.A.\u3001\u4ea7\u54c1\u8bbe\u8ba1 B.A.\uff09\u800c\u975e\u8ba1\u7b97\u673a\u79d1\u5b66\uff0c\u76ee\u524d\u8fd8\u6ca1\u6709\u7b2c\u4e00\u4f5c\u8005\u8bba\u6587\uff08\u6709\u4e24\u7bc7\u5408\u8457\u7684 MR \u8bba\u6587\uff09\u3002\u6211\u80fd\u5e26\u6765\u7684\u662f\u53ef\u8fd0\u884c\u7684\u539f\u578b\u3001\u4e00\u9879 MR \u9886\u57df\u7684\u5df2\u6388\u6743\u53d1\u660e\u4e13\u5229\uff0c\u4ee5\u53ca\u4e00\u5957\u5b9e\u8df5\u578b\u7814\u7a76\u65b9\u6cd5\uff0c\u6211\u4f1a\u5728\u65e9\u671f\u5c31\u628a\u5b83\u8f6c\u5316\u4e3a\u7ecf\u540c\u884c\u8bc4\u5ba1\u7684\u7814\u7a76\u3002\\n\\n\u6211\u4e86\u89e3\u5230\u535a\u58eb\u8bba\u6587\u9700\u8981\u4e00\u4f4d\u5177\u6709 HDR\uff08\u535a\u58eb\u6307\u5bfc\u8d44\u683c\uff09\u7684\u5bfc\u5e08\uff0c\u5982\u8499\u60a8\u5efa\u8bae M\u00e9adel \u6559\u6388\u6216 CARISM \u7684\u5176\u4ed6\u540c\u4e8b\u80fd\u5426\u4e0e\u60a8\u5171\u540c\u6307\u5bfc\uff0c\u6211\u5c06\u4e0d\u80dc\u611f\u6fc0\u3002\u6211\u5f88\u4e50\u610f\u5bc4\u4e0a\u4e00\u4efd\u4e24\u9875\u7684\u7814\u7a76\u8ba1\u5212\u3002\\n\\n\u6b64\u81f4\\n\u656c\u793c\\nHanlei (Eli) Zeng\uff08\u66fe\u97e9\u64c2\uff09\\n\u4e2d\u56fd\u6cc9\u5dde\u534e\u5149\u804c\u4e1a\u5b66\u9662 \u6570\u5b57\u975e\u9057\u8bbe\u8ba1\u4e0e\u5236\u4f5c\u6559\u7814\u5ba4\u4e3b\u4efb\\n\u4f5c\u54c1\u96c6\u4e0e\u7b80\u5386\uff1ahttps://cooleli.github.io/CV-project/v2/\"}, \"phd_students\": {\"found\": false, \"students\": [], \"total_estimate\": \"0\uff082022 \u5e74\u521a\u5728 M\u00e9adel \u6307\u5bfc\u4e0b\u83b7\u535a\u58eb\uff0c\u73b0\u4e3a\u8bb2\u5e08/MCF\uff0c\u65e0 HDR\uff0ctheses.fr \u672a\u89c1\u5176\u6307\u5bfc\u7684\u535a\u58eb\u8bba\u6587\uff09\", \"student_pattern_zh\": \"\u65e0\u535a\u58eb\u751f\uff1b\u672c\u4eba\u7814\u7a76\u65b9\u5411\u4e3a\u7f51\u7edc\u4e0a\u6982\u5ff5\u6d41\u901a\u3001\u865a\u62df\u4e16\u754c\u793e\u4f1a\u5b66\uff082025 \u5e74\u201c\u865a\u62df\u793e\u4f1a\u5b66\u201d\u7814\u8ba8\u4f1a\uff09\u3002\", \"design_background_ok_zh\": \"\u65e0\u5b66\u751f\u8bc1\u636e\u3002\", \"chinese_students_zh\": \"\u65e0\u3002\", \"implication_zh\": \"\u4e0d\u5177\u5907\u72ec\u7acb\u6307\u5bfc\u535a\u58eb\u8d44\u683c\uff08\u65e0 HDR\uff09\uff0c\u4e0d\u5efa\u8bae\u4f5c\u4e3a\u5bfc\u5e08\uff1b\u5982\u5bf9\u201c\u865a\u62df\u4e16\u754c\u793e\u4f1a\u5b66\u201d\u611f\u5174\u8da3\uff0c\u5e94\u901a\u8fc7 M\u00e9adel \u6216 CARISM \u6709 HDR \u7684\u6559\u6388\u7533\u8bf7\u3002\", \"sources\": [\"https://theses.fr/2022ASSA0036\", \"https://carism.assas-universite.fr/sites/default/files/document/cvpublications/2026-cv-jaerciodasilva.pdf\"], \"searched\": [\"theses.fr\uff08\u4f5c\u4e3a\u4f5c\u8005\u51fa\u73b0\u4e8e M\u00e9adel \u540d\u4e0b 2022 \u5e74\u8bba\u6587\uff09\", \"CARISM \u4e2a\u4eba\u9875\u4e0e CV\uff08\u8f93\u5165\u6e90\uff09\"]}, \"title_zh\": \"Ma\u00eetre de conf\u00e9rences\uff08\u4fe1\u606f\u4e0e\u4f20\u64ad\u79d1\u5b66\uff09\uff1b\u4fe1\u606f\u4f20\u64ad\u5b66\u58eb\u9879\u76ee\u4e3b\u4efb\", \"unit_zh\": \"\u6cd5\u56fd\u65b0\u95fb\u5b66\u9662\uff08IFP\uff09/ CARISM\uff0c\u5df4\u9ece-\u5148\u8d24\u7960-\u963f\u8428\u65af\u5927\u5b66\", \"email_hook_zh\": \"\u60a8\u76ee\u524d\u5173\u4e8e\u6c89\u6d78\u5f0f\u4e0e\u751f\u6210\u5f0f\u6280\u672f\u4f5c\u4e3a\u6587\u5316\u4ea7\u4e1a\u65b0\u5174\u9886\u57df\u7684\u7814\u7a76\uff0c\u4e0e\u50cf\u6211\u8fd9\u6837\u7684\u9057\u4ea7 XR \u539f\u578b\u5982\u4f55\u88ab\u91c7\u7eb3\u76f4\u63a5\u76f8\u5173\u3002\", \"csc_status_zh\": \"\u672a\u627e\u5230\"}, {\"name\": \"Klas Karlgren\", \"school_en\": \"Karolinska Institutet\", \"school_zh\": \"\u5361\u7f57\u6797\u65af\u5361\u533b\u5b66\u9662\", \"country\": \"\", \"title\": \"Principal Researcher, Docent; leader of the MINT team\", \"unit\": \"Department of Learning, Informatics, Management and Ethics (LIME), Health Informatics\", \"homepage\": \"https://ki.se/en/people/klas-karlgren\", \"email\": \"klas.karlgren@ki.se\", \"relevance\": 3, \"claim\": \"\u5361\u7f57\u6797\u65af\u5361\u662f\u7eaf\u533b\u5b66\u9662\uff0c\u5168\u6821\u4e0e\u7528\u6237\u65b9\u5411\u6700\u63a5\u8fd1\u7684\u662f Karlgren\uff1a\u4ea4\u4e92\u8bbe\u8ba1/\u4eba\u673a\u4ea4\u4e92\u51fa\u8eab\uff0c\u7528\u8bbe\u8ba1\u79d1\u5b66\u65b9\u6cd5\u505a\u533b\u5b66\u6559\u80b2\u4e2d\u7684\u6a21\u62df\u8bad\u7ec3\u3001\u865a\u62df\u75c5\u4eba\u4e0e\u6e38\u620f\u5316\u2014\u2014\u5c5e\u4e8e\u76f8\u90bb\u65b9\u5411\uff0c\u76f8\u5173\u5ea6\u4f4e\u3002\", \"evidence_homepage\": \"https://ki.se/en/people/klas-karlgren\", \"evidence_papers\": [{\"title\": \"Exploring the potential of gamified virtual patients for military trauma care training: a systematic text condensation analysis\", \"year\": 2026, \"venue\": \"Injury \u2013 International Journal of the Care of the Injured 57(5):113020\", \"url\": \"https://ki.se/en/people/klas-karlgren\", \"link_to_user\": \"\u865a\u62df\u75c5\u4eba/\u6e38\u620f\u5316\u8bbe\u8ba1 \u2192 \u4e0e\u7528\u6237'\u4ea4\u4e92\u539f\u578b\u4f5c\u4e3a\u5b66\u4e60\u5a92\u4ecb'\u7684\u601d\u8def\u76f8\u901a\uff0c\u4f46\u9886\u57df\u662f\u533b\u5b66\", \"title_zh\": \"\u63a2\u7d22\u6e38\u620f\u5316\u865a\u62df\u75c5\u4eba\u5728\u519b\u4e8b\u521b\u4f24\u6551\u6cbb\u8bad\u7ec3\u4e2d\u7684\u6f5c\u529b\uff1a\u7cfb\u7edf\u6587\u672c\u6d53\u7f29\u5206\u6790\"}, {\"title\": \"Game Elements in Military Trauma Simulations: Results from a Systematic Review\", \"year\": 2026, \"venue\": \"Prehospital and Disaster Medicine 41(S1):s71\", \"url\": \"https://ki.se/en/people/klas-karlgren\", \"link_to_user\": \"\u6a21\u62df\u4e2d\u7684\u6e38\u620f\u5143\u7d20 \u2192 \u53ef\u8fc1\u79fb\u5230\u535a\u7269\u9986\u4e92\u52a8\u7684'\u4eea\u5f0f\u5316\u4ea4\u4e92'\u8bbe\u8ba1\", \"title_zh\": \"\u519b\u4e8b\u521b\u4f24\u6a21\u62df\u4e2d\u7684\u6e38\u620f\u5143\u7d20\uff1a\u7cfb\u7edf\u7efc\u8ff0\u7ed3\u679c\"}, {\"title\": \"Considering the ethics of live tissue training in trauma surgery\", \"year\": 2026, \"venue\": \"Journal of Medical Ethics 52(8):552-559\", \"url\": \"https://ki.se/en/people/klas-karlgren\", \"link_to_user\": \"\u8bf4\u660e\u5176\u8bfe\u9898\u6838\u5fc3\u5728\u533b\u5b66\u6559\u80b2\u4f26\u7406\uff0c\u4e0e\u6587\u5316\u9057\u4ea7\u65e0\u5173\", \"title_zh\": \"\u5173\u4e8e\u521b\u4f24\u5916\u79d1\u6d3b\u4f53\u7ec4\u7ec7\u8bad\u7ec3\u7684\u4f26\u7406\u601d\u8003\"}], \"evidence_projects_funding\": \"MINT \u56e2\u961f\uff1a\u5206\u6790\u533b\u7597\u5b66\u4e60\u4e2d\u7684\u4e92\u52a8\u4e0e\u5b9e\u8df5\u5e76\u8bbe\u8ba1\u652f\u6301\u6280\u672f\uff08\u8bbe\u8ba1\u79d1\u5b66\u65b9\u6cd5\uff09\uff1b\u56e2\u961f\u9879\u76ee UM-HEART-VR \u7528 VR \u6559\u6388\u533b\u5b66\u751f\u5171\u60c5\u4e0e\u6c9f\u901a\u3002\", \"fit_to_user\": \"\u53ef\u63d0\u4f9b'\u8bbe\u8ba1\u79d1\u5b66 + \u6a21\u62df/VR \u5b66\u4e60\u8bc4\u4f30'\u7684\u65b9\u6cd5\u8bad\u7ec3\uff1b\u82e5\u7528\u6237\u613f\u610f\u628a\u624b\u52bf\u4ea4\u4e92\u8f6c\u5411\u533b\u5b66\u6559\u80b2\u6216\u5eb7\u590d\u573a\u666f\uff0cKarlgren \u662f KI \u552f\u4e00\u5408\u7406\u5165\u53e3\u3002\", \"counterargument_risk\": \"\u4e0e\u535a\u7269\u9986/\u6587\u5316\u9057\u4ea7/\u53d9\u4e8b\u7167\u660e\u65b9\u5411\u57fa\u672c\u4e0d\u76f8\u5173\uff1bKI \u535a\u58eb\u987b\u5728\u533b\u5b66/\u5065\u5eb7\u6846\u67b6\u4e0b\u7acb\u9898\uff1bCSC \u7ebf\u636e\u8f93\u5165\u5df2\u6682\u505c\u6216\u505c\u6b62\u3002\u5b9e\u9645\u4e0d\u5efa\u8bae\u4f18\u5148\u6295\u5165\u3002\", \"email_hook\": \"Your design-science work on gamified virtual patients is the closest point at KI to my interest in how embodied interaction prototypes shape learning.\", \"sources\": [\"https://ki.se/en/people/klas-karlgren\", \"https://ki.se/en/research/research-areas-centres-and-networks/research-groups/mint-klas-karlgrens-team\"], \"verified\": true, \"csc_note\": \"\u636e\u8f93\u5165 CSC \u7ebf\u72b6\u6001 paused_or_stopped\uff1b\u745e\u5178\u535a\u58eb\u4e3a\u5e26\u85aa\u96c7\u5458\u5236\u5c97\u4f4d\uff0c\u901a\u5e38\u987b\u7533\u8bf7\u9662\u7cfb\u516c\u5f00\u62db\u8058\u7684\u535a\u58eb\u804c\u4f4d\uff08\u6216\u81ea\u5e26\u5168\u989d\u8d44\u52a9\uff09\uff0c\u5957\u78c1\u7684\u4f5c\u7528\u662f\u8ba9\u5bfc\u5e08\u5728\u5c97\u4f4d\u53d1\u5e03\u65f6\u60f3\u5230\u4f60\u3002\", \"matched_keywords\": [\"interaction design\", \"simulation / VR learning\", \"design science\"], \"csc_status\": \"paused_or_stopped\", \"in_user_csc_list\": true, \"email_draft\": {\"to\": \"klas.karlgren@ki.se\", \"subject\": \"PhD enquiry: embodied interaction prototypes and learning (design-science approach)\", \"body\": \"Dear Dr Karlgren,\\n\\nYour design-science work on gamified virtual patients for trauma training, and your interest in capturing the details of learning activities, is the closest point I have found at Karolinska Institutet to my own question of how embodied interaction prototypes shape learning. I am preparing to start a PhD in autumn 2027.\\n\\nSince November 2025 I have directed the Digital ICH Design and Production Teaching and Research Office at Quanzhou Huaguang College, teaching 3D character design, digital sculpting and cultural-product design, supervising student 3D content production and leading a VR collaborative lighting design project (JAT251371). Previously, as a lighting hardware product manager, I ran nine product families at OSRAM/LEDVANCE (~100 SKUs, ~US$8M in sales), including light-distribution analysis for Abu Dhabi's Zayed Airport, and led user research (Amazon data, DEMATEL) at LEEDARSON for smart-lighting lines selling over US$30M. As a teacher I observe learning daily, and my office offers students for prototype studies.\\n\\nMy most relevant prototype is Stone Reveal (https://cooleli.github.io/Portfolio-page/Dunhuang%20Interactive%20Heritage%20project/): four Dunhuang Buddha figures as Three.js particle clouds; with in-browser MediaPipe hand tracking, visitors brush away the \\\"dust\\\" and join palms to reveal the gilded figure. A companion project does this for Chinese bronzes.\\n\\nMy core interest is gesture-driven interaction in cultural heritage, but the underlying question is transferable: how bodily, ritual-like interaction and responsive feedback affect attention, understanding and engagement, studied through prototypes and careful observation. I would be open to framing a PhD around embodied interaction for health-professions learning or rehabilitatio");